  ('revised-k10-grade-1-gmrc:standard:performance:period-3:item-2', 'revised-k10-grade-1-gmrc', 3, 'D14', 'performance', 'Naisasagawa ng mag-aaral ang mga tagubilin ng pamilya sa wastong pakikihalubilo sa kapuwa bilang tanda ng may tiwala sa sarili', 2, 45),
  ('revised-k10-grade-1-gmrc:standard:performance:period-3:item-3', 'revised-k10-grade-1-gmrc', 3, 'D15', 'performance', 'Naisasagawa ng mag-aaral ang mga gawain na tumutugon sa pangangailangan ng kapuwa na nagpapakita ng pagiging mapagbigay..', 3, 46),
  ('revised-k10-grade-1-gmrc:standard:performance:period-3:item-4', 'revised-k10-grade-1-gmrc', 3, 'D16', 'performance', 'Naisasagawa ng mag-aaral ang mga wastong kilos sa loob at labas ng pook-dalanginan na dapat sundin ng mga bata bilang tanda ng pagiging magalang.', 4, 47),
  ('revised-k10-grade-1-gmrc:standard:performance:period-3:item-5', 'revised-k10-grade-1-gmrc', 3, 'D17', 'performance', 'Naisasagawa ng mag-aaral ang mga gawaing pangkapaligiran sa paaralan o pamayanan bilang tanda ng pagiging malinis.', 5, 48),
  ('revised-k10-grade-1-gmrc:standard:performance:period-3:item-6', 'revised-k10-grade-1-gmrc', 3, 'D18', 'performance', 'Naisasagawa ng mag-aaral ang pag-aangkop ng mga pansariling kilos batay sa ipinakitang kabayanihan ng kapuwa-bata bilang tanda ng pagiging mapagmalasakit.', 6, 49),
  ('revised-k10-grade-1-gmrc:standard:content:period-4:item-1', 'revised-k10-grade-1-gmrc', 4, 'D19', 'content', 'Natututuhan ng mag-aaral ang pag-unawa sa sariling tungkulin bilang kasapi ng pamayanan.', 1, 50),
  ('revised-k10-grade-1-gmrc:standard:content:period-4:item-2', 'revised-k10-grade-1-gmrc', 4, 'D20', 'content', 'Natututuhan ng mag-aaral ang pag-unawa sa pakikibahagi ng pamilya sa pamayanan.', 2, 51),
  ('revised-k10-grade-1-gmrc:standard:content:period-4:item-3', 'revised-k10-grade-1-gmrc', 4, 'D21', 'content', 'Natututuhan ng mag-aaral ang pag-unawa sa mga gawain ng mga taong tumutulong sa pamayanan.', 3, 52),
  ('revised-k10-grade-1-gmrc:standard:content:period-4:item-4', 'revised-k10-grade-1-gmrc', 4, 'D22', 'content', 'Natututuhan ng mag-aaral ang pag-unawa sa mga gawaing panrelihiyon o paniniwala sa pamayanan.', 4, 53),
  ('revised-k10-grade-1-gmrc:standard:content:period-4:item-5', 'revised-k10-grade-1-gmrc', 4, 'D23', 'content', 'Natututuhan ng mag-aaral ang pag-unawa sa pangangalaga sa kapaligiran tungo sa malinis na pamayanan.', 5, 54),
  ('revised-k10-grade-1-gmrc:standard:content:period-4:item-6', 'revised-k10-grade-1-gmrc', 4, 'D24', 'content', 'Natututuhan ng mag-aaral ang pag-unawa sa watawat bilang pangunahing sagisag ng bayan.', 6, 55),
  ('revised-k10-grade-1-gmrc:standard:performance:period-4:item-1', 'revised-k10-grade-1-gmrc', 4, 'D19', 'performance', 'Naisasagawa ng mag-aaral ang mga sariling tungkulin bilang kasapi ng pamayanan bilang tanda ng pagiging responsable.', 1, 50),
  ('revised-k10-grade-1-gmrc:standard:performance:period-4:item-2', 'revised-k10-grade-1-gmrc', 4, 'D20', 'performance', 'Naisasagawa ng mag-aaral ang mga sariling tungkulin sa pakikiisa ng pamilya sa pamayanan na nagpapakita ng pagiging mabuting mamamayan.', 2, 51),
  ('revised-k10-grade-1-gmrc:standard:performance:period-4:item-3', 'revised-k10-grade-1-gmrc', 4, 'D21', 'performance', 'Naisasagawa ng mag-aaral ang mga paraan upang maunawaan ang mga gawain ng mga taong tumutulong sa pamayanan bilang tanda ng pagiging mapagmalasakit', 3, 52),
  ('revised-k10-grade-1-gmrc:standard:performance:period-4:item-4', 'revised-k10-grade-1-gmrc', 4, 'D22', 'performance', 'Naisasagawa ng mag-aaral ang pagkilala sa iba’t ibang gawaing panrelihiyon o paniniwala sa pamayanan upang malinang ang pagiging magalang.', 4, 53),
  ('revised-k10-grade-1-gmrc:standard:performance:period-4:item-5', 'revised-k10-grade-1-gmrc', 4, 'D23', 'performance', 'Naisasagawa ng mag-aaral ang mga paraan ng pangangalaga sa kapaligiran upang mapanatili ang kalinisan ng pamayanan ayon sa kakayahan upang malinang ang pagiging mapagmalasakit.', 5, 54),
  ('revised-k10-grade-1-gmrc:standard:performance:period-4:item-6', 'revised-k10-grade-1-gmrc', 4, 'D24', 'performance', 'Naisasagawa ng mag-aaral ang mga angkop na kilos ng pagkilala sa watawat bilang pangunahing sagisag ng bayan upang malinang ang pagmamahal sa bayan.', 6, 55),
  ('revised-k10-grade-1-language:standard:content:period-1:item-1', 'revised-k10-grade-1-language', 1, null, 'content', 'The learners demonstrate developmentally-appropriate language for interacting with others in the classroom, and expressing meanings about familiar topics; they engage with and enjoy listening to a range of texts; and recognize familiar images, icons, and symbols in their environment.', 1, 36),
  ('revised-k10-grade-1-language:standard:performance:period-1:item-1', 'revised-k10-grade-1-language', 1, null, 'performance', 'The learners use their developing vocabulary to talk about themselves, their families, and other everyday topics; they follow teacher’s instructions and answer questions. They listen to and respond to stories; and identify images, icons, and symbols from the environment and familiar texts.', 1, 36),
  ('revised-k10-grade-1-language:standard:content:period-2:item-1', 'revised-k10-grade-1-language', 2, null, 'content', 'The learners demonstrate ongoing development in decoding images, symbols, and content-specific vocabulary; they understand and create simple sentences in getting and expressing meaning about one’s school and everyday topics (narrative and informational); and they recognize features of their language and other languages in their environment.', 1, 39),
  ('revised-k10-grade-1-language:standard:performance:period-2:item-1', 'revised-k10-grade-1-language', 2, null, 'performance', 'The learners use their developing vocabulary to communicate with others, respond to instructions, ask questions, and express ideas; and share personal experiences about one’s school and content-specific topics.', 1, 39),
  ('revised-k10-grade-1-language:standard:content:period-3:item-1', 'revised-k10-grade-1-language', 3, null, 'content', 'The learners demonstrate ongoing development in decoding images, symbols, and high-frequency and content-specific vocabulary; they understand and create simple sentences in getting and retelling information from texts, about one’s community and everyday topics (narrative and informational); and they recognize how language reflect cultural practices and norms in their environment.', 1, 42),
  ('revised-k10-grade-1-language:standard:performance:period-3:item-1', 'revised-k10-grade-1-language', 3, null, 'performance', 'The learners use their developing vocabulary to communicate with others, record, report ideas and retell information and share personal experiences in relation to the texts they viewed or listened to, their community, and content-specific topics.', 1, 42),
  ('revised-k10-grade-1-language:standard:content:period-4:item-1', 'revised-k10-grade-1-language', 4, null, 'content', 'The learners demonstrate ongoing development in decoding images, symbols, and high-frequency and content-specific vocabulary; they understand and create simple sentences in getting and inferring information from texts and expressing meanings about one’s environment and everyday topics (narrative and informational); and they recognize how languages and culture are interrelated.', 1, 45),
  ('revised-k10-grade-1-language:standard:performance:period-4:item-1', 'revised-k10-grade-1-language', 4, null, 'performance', 'The learners use their developing vocabulary to communicate with others, participate in classroom interactions, draw and discuss information from texts; and share personal experiences in relation to the texts they viewed or listened to, their environment, and content-specific topics.', 1, 45),
  ('revised-k10-grade-1-makabansa:standard:content:period-1:item-1', 'revised-k10-grade-1-makabansa', 1, null, 'content', 'Nauunawaan na ang bawat tao ay may indibidwalidad (individuality)', 1, 16),
  ('revised-k10-grade-1-makabansa:standard:performance:period-1:item-1', 'revised-k10-grade-1-makabansa', 1, null, 'performance', 'Naipapamalas na ang bawat tao ay may indibidwalidad', 1, 16),
  ('revised-k10-grade-1-makabansa:standard:content:period-2:item-1', 'revised-k10-grade-1-makabansa', 2, null, 'content', 'Nauunawaan ang mga bahaging ginagampanan at tungkulin bilang kasapi ng pamilya', 1, 17),
  ('revised-k10-grade-1-makabansa:standard:performance:period-2:item-1', 'revised-k10-grade-1-makabansa', 2, null, 'performance', 'Nakagagawa ng likhang-sining na nagpapakita ng papel at tungkulin ng mga kasapi ng pamilya', 1, 17),
  ('revised-k10-grade-1-makabansa:standard:content:period-3:item-1', 'revised-k10-grade-1-makabansa', 3, null, 'content', 'Nauunawaan ang pagkakakilanlan ng sariling paaralan at ng mga taong bumubuo rito', 1, 18),
  ('revised-k10-grade-1-makabansa:standard:performance:period-3:item-1', 'revised-k10-grade-1-makabansa', 3, null, 'performance', 'Nakagagawa ng likhang-sining (mapa) tungkol sa sariling paaralan', 1, 18),
  ('revised-k10-grade-1-makabansa:standard:content:period-4:item-1', 'revised-k10-grade-1-makabansa', 4, null, 'content', 'Nauunawaan ang papel ng mga kasapi ng kinabibilangang pamayanan', 1, 19),
  ('revised-k10-grade-1-makabansa:standard:performance:period-4:item-1', 'revised-k10-grade-1-makabansa', 4, null, 'performance', 'Nakalalahok sa mga gawaing nagpapahalaga sa kinabibilangang pamayanan', 1, 19),
