  ('revised-k10-grade-1-mathematics:standard:performance:period-4:item-2', 'revised-k10-grade-1-mathematics', 4, 'D02', 'performance', 'recognize, and determine the value of, Philippine coins and bills up to ₱100. (NA)', 2, 28),
  ('revised-k10-grade-1-mathematics:standard:performance:period-4:item-3', 'revised-k10-grade-1-mathematics', 4, 'D02', 'performance', 'add money where the sum is up to ₱100 and subtract money where both amounts are less than ₱100. (NA)', 3, 28),
  ('revised-k10-grade-1-mathematics:standard:performance:period-4:item-4', 'revised-k10-grade-1-mathematics', 4, 'D01', 'performance', 'identify the position of an object following a half turn or quarter turn, in clockwise or counter-clockwise direction. (MG)', 4, 28),
  ('revised-k10-grade-1-mathematics:standard:performance:period-4:item-5', 'revised-k10-grade-1-mathematics', 4, 'D01', 'performance', 'identify and work with time measured in hours, half hours, quarter hours, days, weeks, months, and years. (MG)', 5, 28),
  ('revised-k10-grade-1-reading-and-literacy:standard:content:period-1:item-1', 'revised-k10-grade-1-reading-and-literacy', 1, null, 'content', 'The learners demonstrate phonological awareness in decoding developmentally-and grade level-appropriate words; understand and create simple sentences to express meaning about oneself, family, and everyday topics (narrative and informational).', 1, 36),
  ('revised-k10-grade-1-reading-and-literacy:standard:performance:period-1:item-1', 'revised-k10-grade-1-reading-and-literacy', 1, null, 'performance', 'The learners use phonological and alphabetic knowledge to read/write words accurately with/for meaning and narrate personal experiences with family and content-specific topics.', 1, 36),
  ('revised-k10-grade-1-reading-and-literacy:standard:content:period-2:item-1', 'revised-k10-grade-1-reading-and-literacy', 2, null, 'content', 'The learners demonstrate ongoing development in decoding high frequency words and content-specific vocabulary; understand and create simple sentences in getting and expressing meaning about one’s school and everyday topics (narrative and informational).', 1, 39),
  ('revised-k10-grade-1-reading-and-literacy:standard:performance:period-2:item-1', 'revised-k10-grade-1-reading-and-literacy', 2, null, 'performance', 'The learners use their developing word knowledge in automatically recognizing sight words; decode high frequency words and content-specific vocabulary and use them to express ideas; and narrate personal experiences with one’s school and content-specific topics.', 1, 39),
  ('revised-k10-grade-1-reading-and-literacy:standard:content:period-3:item-1', 'revised-k10-grade-1-reading-and-literacy', 3, null, 'content', 'The learners demonstrate ongoing development in decoding high frequency words and content-specific vocabulary; understand and create simple sentences in getting and expressing meaning about one’s community and content-specific topics (narrative and informational).', 1, 41),
  ('revised-k10-grade-1-reading-and-literacy:standard:performance:period-3:item-1', 'revised-k10-grade-1-reading-and-literacy', 3, null, 'performance', 'The learners use their ongoing development in automatically recognizing sight words; decode high frequency words and content-specific vocabulary and use them to express ideas; read sentences and narrate personal experience with one’s community and content-specific topics.', 1, 41),
  ('revised-k10-grade-1-reading-and-literacy:standard:content:period-4:item-1', 'revised-k10-grade-1-reading-and-literacy', 4, null, 'content', 'The learners demonstrate ongoing development in decoding high frequency words and content specific vocabulary; understand and create simple sentences in getting and expressing meaning about one’s environment and content-specific topics (narrative and informational).', 1, 43),
  ('revised-k10-grade-1-reading-and-literacy:standard:performance:period-4:item-1', 'revised-k10-grade-1-reading-and-literacy', 4, null, 'performance', 'The learners automatically recognize sight words, decode words, express ideas; read sentences with appropriate speed, accuracy, and expression; and narrate personal experiences with one’s environment and content-specific topics.', 1, 43),
  ('revised-k10-grade-10-english:standard:content:period-1:item-1', 'revised-k10-grade-10-english', 1, null, 'content', 'The learners demonstrate their multiliteracies and communicative competence in evaluating World literature (poetry, prose, and drama) for clarity of meaning, purpose, and target audience as a foundation for publishing original literary texts that reflect their expanding cultural identity.', 1, 175),
  ('revised-k10-grade-10-english:standard:performance:period-1:item-1', 'revised-k10-grade-10-english', 1, null, 'performance', 'The learners analyze the style, form, and features of World literature (poetry, prose, and drama); evaluate literary texts for clarity of meaning, purpose, and target audience; and compose and publish an original multimodal literary text (short film) that represents their meaning, purpose, and target audience, and reflects their expanding cultural identity.', 1, 175),
  ('revised-k10-grade-10-english:standard:content:period-2:item-1', 'revised-k10-grade-10-english', 2, null, 'content', 'The learners demonstrate their multiliteracies and communicative competence in evaluating informational texts (journalistic texts: documentaries and vlogs) for clarity of meaning, purpose, and target audience as a foundation for publishing original informational texts.', 1, 177),
  ('revised-k10-grade-10-english:standard:performance:period-2:item-1', 'revised-k10-grade-10-english', 2, null, 'performance', 'The learners analyze the style, form, and features of informational texts (documentaries and vlogs); evaluate informational texts for clarity of meaning, purpose, and target audience; and compose and publish original multimodal informational texts (documentaries and vlogs) using appropriate forms and structures that represent their meaning, purpose, and target audience.', 1, 177),
  ('revised-k10-grade-10-english:standard:content:period-3:item-1', 'revised-k10-grade-10-english', 3, null, 'content', 'The learners demonstrate their multiliteracies and communicative competence in evaluating informational texts (research report [stage 1] based on literature review) and transactional texts (letter of application) for clarity of meaning, purpose, and target audience as a foundation for publishing original informational and transactional texts.', 1, 180),
  ('revised-k10-grade-10-english:standard:performance:period-3:item-1', 'revised-k10-grade-10-english', 3, null, 'performance', 'The learners analyze the style, form, and features of informational texts (research report based on literature review) and transactional texts (letter of application); evaluate informational and transactional texts for clarity of meaning, purpose, and target audience; and compose and publish original multimodal informational texts (research report [stage 1] based on literature review) and transactional texts (letter of application) using appropriate forms and structures that represent their meaning, purpose, and target audience.', 1, 180),
  ('revised-k10-grade-10-english:standard:content:period-4:item-1', 'revised-k10-grade-10-english', 4, null, 'content', 'The learners demonstrate their multiliteracies and communicative competence in evaluating informational texts (research report [stage 2] based on literature review) for clarity of meaning, purpose, and target audience as a foundation for publishing original informational texts.', 1, 183),
  ('revised-k10-grade-10-english:standard:performance:period-4:item-1', 'revised-k10-grade-10-english', 4, null, 'performance', 'The learners analyze the style, form, and features of informational texts (research report based on literature review); evaluate informational texts for clarity of meaning, purpose, and target audience; and compose and publish original multimodal informational texts (research report [stage 2] based on literature review) using appropriate forms and structures that represent their meaning, purpose, and target audience.', 1, 183),
  ('revised-k10-grade-10-filipino:standard:content:period-1:item-1', 'revised-k10-grade-10-filipino', 1, null, 'content', 'Naipamamalas ng mga mag-aaral ang kasanayang komunikatibo, pagiging malikhain, at kritikal na pag-unawa at pagsusuri ng Obra Maestra – El Filibusterismo para sa pagtatamo ng kaunlaran at pagtugon sa pandaigdigang pakikipag-ugnayan at pagbuo ng mga teksto sa iba’t ibang paraan (mutimodal) para sa tiyak na layunin, pagpapakahulugan, at target na babasa o awdiyens.', 1, 161),
  ('revised-k10-grade-10-filipino:standard:performance:period-1:item-1', 'revised-k10-grade-10-filipino', 1, null, 'performance', 'Nakabubuo ng documentary film ng El Filibusterismo na naipakikita ang kaunlaran sa usaping panlipunan na isinasaalang-alang ang elemento ng biswal at multimodal na may paglalapat ng kasanayang komunikatibo at etikal na kasanayan at pananagutan.', 1, 161),
  ('revised-k10-grade-10-filipino:standard:content:period-2:item-1', 'revised-k10-grade-10-filipino', 2, null, 'content', 'Naipamamalas ng mag-aaral ang kasanayang komunikatibo, pagiging malikhain, at kritikal na pag-unawa at pagsusuri ng mga tekstong pampanitikan (sa Kontemporaneong Panahon /Makabagong Panahon), impormasyonal, akademik para sa pagtatamo ng kaunlaran at pagtugon sa pandaigdigang pakikipag-ugnayan, at pagbuo ng mga teksto sa iba’t ibang paraan (multimodal) para sa tiyak na layunin, pagpapakahulugan, at target na babasa o awdiyens.', 1, 165),
  ('revised-k10-grade-10-filipino:standard:performance:period-2:item-1', 'revised-k10-grade-10-filipino', 2, null, 'performance', 'Nakabubuo ng isang grapikong representasyon mula sa sarbey na isinasaalang-alang ang mga elemento ng biswal at multimodal na may paglalapat ng kasanayang komunikatibo at etikal na kasanayan at pananagutan.', 1, 165),
  ('revised-k10-grade-10-filipino:standard:content:period-3:item-1', 'revised-k10-grade-10-filipino', 3, null, 'content', 'Naipamamalas ng mag-aaral ang kasanayang komunikatibo, pagtataya sa realidad at pagsasaalang-alang sa mekaniks ng pag-alam sa batayang kaalaman sa tekstong akademik sa pagtatamo ng kaunlaran at pagtugon sa pandaigdigang pakikipag-ugnayan at pagbuo ng mga teksto sa iba’t ibang paraan (multimodal) para sa tiyak na layunin, pagpapakahulugan, at target na babasa o awdiyens.', 1, 168),
  ('revised-k10-grade-10-filipino:standard:performance:period-3:item-1', 'revised-k10-grade-10-filipino', 3, null, 'performance', 'Nakabubuo ng isang konseptuwal na balangkas na isinasaalang-alang ang mga elemento ng biswal at multimodal na may paglalapat ng kasanayang komunikatibo at etikal na kasanayan at pananagutan.', 1, 168),
  ('revised-k10-grade-10-filipino:standard:content:period-4:item-1', 'revised-k10-grade-10-filipino', 4, null, 'content', 'Naipamamalas ng mga mag-aaral ang kasanayang komunikatibo, pagtataya sa realidad at pagsasaalang-alang sa mekaniks sa pag-alam sa batayang kaalaman sa tekstong akademik upang makatugon sa pandaigdigang pakikipag-ugnayan bilang isang makabayang Pilipino.', 1, 170),
  ('revised-k10-grade-10-filipino:standard:performance:period-4:item-1', 'revised-k10-grade-10-filipino', 4, null, 'performance', 'Nakabubuo ng poster presentation ng panukalang pananaliksik na isinasaalang-alang ang mga elemento ng biswal at multimodal na may paglalapat ng kasanayang komunikatibo, at etikal na kasanayan at pananagutan.', 1, 170),
