  ('revised-k10-grade-2-english:standard:content:period-1:item-1', 'revised-k10-grade-2-english', 1, null, 'content', 'The learners demonstrate phonological awareness and phonic knowledge in decoding developmentally-appropriate words; and understand and create simple sentences to express meaning about oneself, family, and everyday topics.', 1, 47),
  ('revised-k10-grade-2-english:standard:performance:period-1:item-1', 'revised-k10-grade-2-english', 1, null, 'performance', 'The learners use phonological, phonic, and alphabet knowledge to read/write words accurately; decode high frequency words and some content-specific vocabulary; use phrases or simple sentences to express ideas about oneself, family, and everyday topics; and read grade level sentences with appropriate speed, accuracy, and expression.', 1, 47),
  ('revised-k10-grade-2-english:standard:content:period-2:item-1', 'revised-k10-grade-2-english', 2, null, 'content', 'The learners demonstrate development in decoding high frequency words and content-specific vocabulary; and understand and create simple sentences in getting and expressing meaning about their school and everyday topics.', 1, 50),
  ('revised-k10-grade-2-english:standard:performance:period-2:item-1', 'revised-k10-grade-2-english', 2, null, 'performance', 'The learners use their developing word knowledge to recognize sight words; decode high frequency words and content-specific vocabulary; use simple sentences to express ideas and narrate personal experiences about their school and content-specific topics; and read grade level sentences with appropriate speed, accuracy, and expression.', 1, 50),
  ('revised-k10-grade-2-english:standard:content:period-3:item-1', 'revised-k10-grade-2-english', 3, null, 'content', 'The learners demonstrate ongoing development in decoding high frequency words and content-specific vocabulary; and understand and create simple sentences in getting and expressing meaning about their community and content-specific topics.', 1, 53),
  ('revised-k10-grade-2-english:standard:performance:period-3:item-1', 'revised-k10-grade-2-english', 3, null, 'performance', 'The learners use their developing word knowledge to recognize sight words; decode high frequency words and content-specific vocabulary; use simple sentences to express ideas and narrate personal experiences about their community and content-specific topics; and read grade level sentences with appropriate speed, accuracy, and expression.', 1, 53),
  ('revised-k10-grade-2-english:standard:content:period-4:item-1', 'revised-k10-grade-2-english', 4, null, 'content', 'The learners demonstrate ongoing development in decoding high frequency words and content-specific vocabulary; understand and create simple sentences in getting and expressing meaning about their environment and content-specific topics.', 1, 57),
  ('revised-k10-grade-2-english:standard:performance:period-4:item-1', 'revised-k10-grade-2-english', 4, null, 'performance', 'The learners use their developing word knowledge to recognize sight words; decode high frequency words and content-specific vocabulary; use simple sentences to express ideas and narrate personal experiences about their environment and content-specific topics; and read grade level sentences with appropriate speed, accuracy, and expression.', 1, 57),
  ('revised-k10-grade-2-filipino:standard:content:period-1:item-1', 'revised-k10-grade-2-filipino', 1, null, 'content', 'Naipamamalas ng mag-aaral ang kahusayan sa kamalayang ponolohikal, pagbigkas at pag-aaral ng mga tunog at salita tungo sa papaunlad na kasanayang panggramatika, pag-unawa at pagsusuri ng tekstong naratibo at impormatibo na magiging daan sa pagbuo ng mga payak na pangungusap at teksto tungkol sa sarili at pamilya na ginagamit sa pang-araw-araw na paksa at sitwasyon.', 1, 21),
  ('revised-k10-grade-2-filipino:standard:performance:period-1:item-1', 'revised-k10-grade-2-filipino', 1, null, 'performance', 'Nagagamit ng mag-aaral ang pagkakaroon ng kahusayan sa kamalayang ponolohikal, pagbigkas ng mga tunog sa pagpapahayag ng ideya, karanasan at pagbasa ng mga pangungusap nang may kawastuhan, katatasan at tamang ekspresyon tungkol sa sarili at pamilya, at pang-araw-araw na paksang naratibo at impormatibo.', 1, 21),
