  ('revised-k10-grade-3-filipino:standard:content:period-1:item-1', 'revised-k10-grade-3-filipino', 1, null, 'content', 'Naipamamalas ng mag-aaral ang kahusayan sa pagbigkas at pag-aaral ng mga tunog at salita tungo sa papaunlad na kasanayang panggramatika, pag-unawa at pagsusuri ng tekstong naratibo at impormatibo na magiging daan sa pagbuo ng mga tambalang pangungusap at teksto tungkol sa sarili at bansa na ginagamit sa pang-araw-araw na paksa at sitwasyon.', 1, 39),
  ('revised-k10-grade-3-filipino:standard:performance:period-1:item-1', 'revised-k10-grade-3-filipino', 1, null, 'performance', 'Nagagamit ng mag-aaral ang pagkakaroon ng kahusayan sa pagbigkas ng mga salita, pagbasa ng mga pangungusap nang may kawastuhan, katatasan at tamang ekspresyon tungkol sa sarili at bansa na ginagamit sa pang-araw-araw na paksa at sitwasyon. Nagiging daan din ito sa pagbuo ng tekstong naratibo at impormatibo sa pagpapahayag ng ideya at karanasan gamit ang mga natutuhan sa gramatika.', 1, 39),
  ('revised-k10-grade-3-filipino:standard:content:period-2:item-1', 'revised-k10-grade-3-filipino', 2, null, 'content', 'Naipamamalas ng mag-aaral ang kahusayan sa pagbigkas at pag-aaral ng mga tunog at salita tungo sa papaunlad na kasanayang panggramatika, pag-unawa at pagsusuri ng tekstong naratibo at impormatibo na magiging daan sa pagbuo ng mga tambalang pangungusap at teksto tungkol sa sarili at bansa na ginagamit sa pang-araw-araw na paksa at sitwasyon.', 1, 43),
