  ('revised-k10-grade-4-epp:standard:performance:period-4:item-2', 'revised-k10-grade-4-epp', 4, null, 'performance', 'Ang mga mag-aaral ay nakagagawa ng proyekto mula sa recyclable materials na maaring pagkakitaan', 2, 45),
  ('revised-k10-grade-4-filipino:standard:content:period-1:item-1', 'revised-k10-grade-4-filipino', 1, null, 'content', 'Naipamamalas ng mag-aaral ang kahusayan sa pagpapalawak ng bokabolaryo, kamalayan sa gramatika (denotasyon, konotasyon), pag-unawa sa tekstong naratibo (alamat, pabula, parabula, at anekdota) at tekstong impormatibo (pag-iisa at paglalarawan), paglinang ng mga kasanayang produktibo gamit ang wika, paggamit ng mga elementong biswal sa pagsusuri, paglalarawan, at pagpapakahulugan upang makalikha ng tekstong tumatalakay sa mga paksang patungkol sa lokal na komunidad at bansa na naaangkop sa edad, nagsasaalang-alang sa kasarian, paksa, at kultura batay sa layunin, konteksto, at target na madla.', 1, 67),
  ('revised-k10-grade-4-filipino:standard:performance:period-1:item-1', 'revised-k10-grade-4-filipino', 1, null, 'performance', 'Nagagamit ng mag-aaral ang pagkakaroon ng kahusayan sa wastong gramatika, kaangkupan ng salita/retorika, estilo, at estruktura sa pagsasalaysay ng nakawiwiling pangyayari na naglalarawan ng isang lokal na komunidad o bansa na karanasan (anekdota).', 1, 67),
  ('revised-k10-grade-4-filipino:standard:content:period-2:item-1', 'revised-k10-grade-4-filipino', 2, null, 'content', 'Naipamamalas ng mag-aaral ang kahusayan sa pagpapalawak ng bokabolaryo, kamalayan sa gramatika (denotasyon, konotasyon), pag-unawa sa tekstong naratibo (anekdota, tulang pambata, at kuwentong-bayan) at tekstong impormatibo (paglalahad muli (recount) gaya ng talaarawan at talambuhay ng sarili), paglinang ng mga kasanayang produktibo gamit ang wika, paggamit ng mga elementong biswal sa pagsusuri, paglalarawan, at pagpapakahulugan upang makalikha ng tekstong tumatalakay sa mga paksang patungkol sa lokal na komunidad at bansa na naaangkop sa edad, nagsasaalang-alang sa kasarian, paksa, at kultura batay sa layunin, konteksto, at target na madla.', 1, 71),
  ('revised-k10-grade-4-filipino:standard:performance:period-2:item-1', 'revised-k10-grade-4-filipino', 2, null, 'performance', 'Nagagamit ng mag-aaral ang pagkakaroon ng kahusayan sa wastong gramatika, kaangkupan ng salita/retorika, estilo, at estruktura sa paggawa ng salaysay ng karanasan sa isang lokal na komunidad o bansa tungkol sa sarili (talambuhay ng sarili o autobiography).', 1, 71),
  ('revised-k10-grade-4-filipino:standard:content:period-3:item-1', 'revised-k10-grade-4-filipino', 3, null, 'content', 'Naipamamalas ng mag-aaral ang kahusayan sa pagpapalawak ng bokabolaryo, kamalayan sa gramatika (denotasyon, konotasyon), pag-unawa sa tekstong naratibo (mito, epiko, tulang pambata, at kuwentong kababalaghan) at tekstong impormatibo (paglalahad muli (recount) ng talambuhay (biography) ng taong may makabuluhang ambag sa lipunan), paglinang ng mga kasanayang produktibo gamit ang wika, paggamit ng mga elementong biswal sa pagsusuri, paglalarawan, at pagpapakahulugan upang makalikha ng tekstong tumatalakay sa mga paksang patungkol sa lokal na komunidad at bansa na naaangkop sa edad, nagsasaalang-alang sa kasarian, paksa, at kultura batay sa layunin, konteksto, at target na madla.', 1, 75),
  ('revised-k10-grade-4-filipino:standard:performance:period-3:item-1', 'revised-k10-grade-4-filipino', 3, null, 'performance', 'Nagagamit ng mag-aaral ang pagkakaroon ng kahusayan sa wastong gramatika, kaangkupan ng salita/retorika, estilo, at estruktura sa paggawa ng talambuhay ng mga Pilipinong may makabuluhang ambag sa lipunang (recount) lokal o bansa.', 1, 75),
  ('revised-k10-grade-4-filipino:standard:content:period-4:item-1', 'revised-k10-grade-4-filipino', 4, null, 'content', 'Naipamamalas ng mag-aaral ang kahusayan sa pagpapalawak ng bokabolaryo, kamalayan sa gramatika (denotasyon, konotasyon), pag-unawa sa tekstong naratibo (mito, epiko, tulang pambata, at kuwentong kababalaghan) at tekstong impormatibo (pagsusunod-sunod sa panuto, hakbang, at proseso), paglinang ng mga kasanayang produktibo gamit ang wika, paggamit ng mga elementong biswal sa pagsusuri, paglalarawan, at pagpapakahulugan upang makalikha ng tekstong tumatalakay sa mga paksang patungkol sa lokal na komunidad at bansa na naaangkop sa edad, nagsasaalang-alang sa kasarian, paksa, at kultura batay sa layunin, konteksto, at target na madla.', 1, 79),
  ('revised-k10-grade-4-filipino:standard:performance:period-4:item-1', 'revised-k10-grade-4-filipino', 4, null, 'performance', 'Nagagamit ng mag-aaral ang pagkakaroon ng kahusayan sa wastong gramatika, kaangkupan ng salita/retorika, estilo, at estruktura sa paggawa ng tulang pambata na nagsasaad ng proseso ng isang gawain sa lokal na komunidad o bansa.', 1, 79),
