  ('revised-k10-grade-6-epp:standard:performance:period-3:item-1', 'revised-k10-grade-6-epp', 3, null, 'performance', 'The learners prepare simple meals following kitchen operations with safety precautions', 1, 66),
  ('revised-k10-grade-6-epp:standard:performance:period-3:item-2', 'revised-k10-grade-6-epp', 3, null, 'performance', 'The learners preserve and sell products with safety precautions.', 2, 66),
  ('revised-k10-grade-6-epp:standard:content:period-4:item-1', 'revised-k10-grade-6-epp', 4, 'D27', 'content', 'demonstrate an understanding of the basic principles of making wood or bamboo works', 1, 67),
