  ('revised-k10-grade-6-epp:standard:performance:period-4:item-1', 'revised-k10-grade-6-epp', 4, null, 'performance', 'The learners perform the basic competencies in wood or bamboo works, sheet metal works, and electrical works with safety precautions', 1, 67),
  ('revised-k10-grade-6-epp:standard:performance:period-4:item-2', 'revised-k10-grade-6-epp', 4, null, 'performance', 'The learners develop and sell simple project with safety precautions', 2, 68),
  ('revised-k10-grade-6-filipino:standard:content:period-1:item-1', 'revised-k10-grade-6-filipino', 1, null, 'content', 'Naipamamalas ng mag-aaral ang kahusayan sa pagpapalawak ng bokabolaryo (denotasyon, konotasyon, tono, at damdamin) na ginagamit sa pormal at di-pormal na mga sitwasyon, lumalagong kaalaman sa mga estrukturang gramatikal, kritikal at lapat na pag-unawa sa tekstong naratibo (tulang pambata, dulang pambata, kuwentong katatakutan, maikling kuwento) at tekstong impormatibo (eksposisyon), pagbuo ng teksto, at kaalaman sa mga di-berbal na pahiwatig (pisikal na paghahatid ng mensahe) at kasanayang produktibo, at paggamit tekstong multimedia sa pagusuri at pagpapakahulugan upang makabuo ng tekstong tumatalakay sa mga paksang patungkol sa bansa at global na may kaangkupan sa edad, kasarian, paksa, at kultura (pasalita, pasulat, at multimedia) na batay sa layunin, konteksto, at target na madla.', 1, 100),
  ('revised-k10-grade-6-filipino:standard:performance:period-1:item-1', 'revised-k10-grade-6-filipino', 1, null, 'performance', 'Nagagamit ng mag-aaral ang pagkakaroon ng kahusayan sa wastong gramatika, kaangkupan ng salita/retorika, estilo, at estruktura sa paggawa ng sanaysay na naglalahad ng tampok na isang pangyayari sa bansa o global.', 1, 100),
  ('revised-k10-grade-6-filipino:standard:content:period-2:item-1', 'revised-k10-grade-6-filipino', 2, null, 'content', 'Naipamamalas ng mag-aaral ang kahusayan sa pagpapalawak ng bokabolaryo (denotasyon, konotasyon, tono, at damdamin) na ginagamit sa pormal at di-pormal na mga sitwasyon, lumalagong kaalaman sa mga estrukturang gramatikal, kritikal at lapat na pag-unawa sa tekstong naratibo (tula, dula, maikling kuwento, at siyensiyang piksyon) at tekstong impormatibo (eksposisyon), pagbuo ng teksto, at kaalaman sa mga di-berbal na pahiwatig (pisikal na paghahatid ng mensahe) at kasanayang produktibo, at paggamit tekstong multimedia sa pagusuri at pagpapakahulugan upang makabuo ng tekstong tumatalakay sa mga paksang tungkol sa bansa at global na may kaangkupan sa edad, kasarian, paksa, at kultura (pasalita, pasulat, at multimedia) na batay sa layunin, konteksto, at target na madla.', 1, 105),
  ('revised-k10-grade-6-filipino:standard:performance:period-2:item-1', 'revised-k10-grade-6-filipino', 2, null, 'performance', 'Nagagamit ng mag-aaral ang pagkakaroon ng kahusayan sa wastong gramatika, kaangkupan ng salita/retorika, estilo, at estruktura sa paggawa ng isang sanaysay tungkol sa isang suliraning pambansa o pangglobal.', 1, 105),
  ('revised-k10-grade-6-filipino:standard:content:period-3:item-1', 'revised-k10-grade-6-filipino', 3, null, 'content', 'Naipamamalas ng mag-aaral ang kahusayan sa pagpapalawak ng bokabolaryo (denotasyon, konotasyon, tono, at damdamin) na ginagamit sa pormal at di-pormal na mga sitwasyon, lumalagong kaalaman sa mga estrukturang gramatikal, kritikal at lapat na pag-unawa sa tekstong naratibo (tula, dula, maikling kuwento, at siyensiyang piksyon) at tekstong impormatibo (panghihikayat/persweysib), pagbuo ng teksto, at kaalaman sa mga di-berbal na pahiwatig (pisikal na paghahatid ng mensahe) at kasanayang produktibo, at paggamit tekstong multimedia sa pagusuri at pagpapakahulugan upang makabuo ng tekstong tumatalakay sa mga paksang tungkol sa bansa at global na may kaangkupan sa edad, kasarian, paksa, at kultura (pasalita, pasulat, at multimedia) na batay sa layunin, konteksto, at target na madla.', 1, 109),
  ('revised-k10-grade-6-filipino:standard:performance:period-3:item-1', 'revised-k10-grade-6-filipino', 3, null, 'performance', 'Nagagamit ng mag-aaral ang pagkakaroon ng kahusayan sa wastong gramatika, kaangkupan ng salita/retorika, estilo, at estruktura sa paggawa ng editoryal tungkol sa isang napapanahong usaping pambansa o pangglobal.', 1, 109),
  ('revised-k10-grade-6-filipino:standard:content:period-4:item-1', 'revised-k10-grade-6-filipino', 4, null, 'content', 'Naipamamalas ng mag-aaral ang kahusayan sa pagpapalawak ng bokabolaryo (denotasyon, konotasyon, tono, at damdamin) na ginagamit sa pormal at di-pormal na mga sitwasyon, lumalagong kaalaman sa mga estrukturang gramatikal, kritikal at lapat na pag-unawa sa tekstong naratibo ((tula, dula, maikling kuwento, at nobela) at tekstong impormatibo (panghihikayat/persuweysib), pagbuo ng teksto, at kaalaman sa mga di-berbal na pahiwatig (pisikal na paghahatid ng mensahe) at kasanayang produktibo, at paggamit tekstong multimedia sa pagusuri at pagpapakahulugan upang makabuo ng tekstong tumatalakay sa mga paksang tungkol sa bansa at global na may kaangkupan sa edad, kasarian, paksa, at kultura (pasalita, pasulat, at multimedia) na batay sa layunin, konteksto, at target na madla.', 1, 113),
  ('revised-k10-grade-6-filipino:standard:performance:period-4:item-1', 'revised-k10-grade-6-filipino', 4, null, 'performance', 'Nagagamit ng mag-aaral ang pagkakaroon ng kahusayan sa wastong gramatika, kaangkupan ng salita/retorika, estilo, at estruktura sa paggawa ng liham paanyaya sa isang tagapagsalita para magbibigay ng panayam sa paksang pambansa o pangglobal.', 1, 113),
  ('revised-k10-grade-6-gmrc:standard:content:period-1:item-1', 'revised-k10-grade-6-gmrc', 1, 'D01', 'content', 'Natututuhan ng mag-aaral ang pag-unawa sa kahalagahan ng pagkilala sa sarili bilang nilikha na may dignidad.', 1, 156),
