  ('revised-k10-grade-7-tle:standard:content:period-2:item-1', 'revised-k10-grade-7-tle', 2, 'D09', 'content', 'demonstrate an understanding of the concepts and skills in agri-crops and animal production', 1, 71),
  ('revised-k10-grade-7-tle:standard:performance:period-2:item-1', 'revised-k10-grade-7-tle', 2, null, 'performance', 'The learners perform agricultural practices in crop production based on industry standards', 1, 72),
