  ('revised-k10-grade-7-values-education:standard:performance:period-4:item-5', 'revised-k10-grade-7-values-education', 4, 'D26', 'performance', 'Naisasagawa ng mag-aaral ang pagninilay sa mga isyu ng bayan bilang bahagi ng espirituwalidad upang malinang ang pagiging matiyaga.', 5, 210),
  ('revised-k10-grade-7-values-education:standard:performance:period-4:item-6', 'revised-k10-grade-7-values-education', 4, 'D27', 'performance', 'Naisasagawa ng mag-aaral ang mga hakbang upang maiangat ang kamalayan sa mga panahanan (habitat) ng mga hayop sa pamayanan upang mapanatili ang pagiging mabuting katiwala.', 6, 211),
  ('revised-k10-grade-7-values-education:standard:performance:period-4:item-7', 'revised-k10-grade-7-values-education', 4, 'D28', 'performance', 'Naisasagawa ng mag-aaral ang produkto o serbisyo na tumutugon sa pangangailangan ng pamayanang kinabibilangan alinsunod sa glokalisasyon upang malinang ang ma-inobasyon na pagiging malikhain.', 7, 212),
  ('revised-k10-grade-8-english:standard:content:period-1:item-1', 'revised-k10-grade-8-english', 1, null, 'content', 'The learners demonstrate their multiliteracies and communicative competence in evaluating Afro-Asian literature (poetry and prose) for clarity of meaning, purpose, and target audience as a foundation for publishing original literary texts that reflect their expanding cultural identity.', 1, 154),
  ('revised-k10-grade-8-english:standard:performance:period-1:item-1', 'revised-k10-grade-8-english', 1, null, 'performance', 'The learners analyze the style, form, and features of Afro-Asian literature (poetry and prose); evaluate literary texts for clarity of meaning, purpose, and target audience; and compose and publish an original multimodal literary text (poem or prose) that represents their meaning, purpose, and target audience, and reflects their expanding cultural identity.', 1, 154),
  ('revised-k10-grade-8-english:standard:content:period-2:item-1', 'revised-k10-grade-8-english', 2, null, 'content', 'The learners demonstrate their multiliteracies and communicative competence in evaluating informational texts (persuasive texts) for clarity of meaning, purpose, and target audience as a foundation for publishing original informational texts.', 1, 156),
  ('revised-k10-grade-8-english:standard:performance:period-2:item-1', 'revised-k10-grade-8-english', 2, null, 'performance', 'The learners analyze the style, form, and features of informational texts (persuasive texts); evaluate informational texts for clarity of meaning, purpose, and target audience; and compose and publish original multimodal informational texts (persuasive texts) using appropriate forms and structures that represent their meaning, purpose, and target audience.', 1, 156),
  ('revised-k10-grade-8-english:standard:content:period-3:item-1', 'revised-k10-grade-8-english', 3, null, 'content', 'The learners demonstrate their multiliteracies and communicative competence in evaluating informational texts (journalistic texts: opinion editorials, sports, and Science and Technology articles) for clarity of meaning, purpose, and target audience as a foundation for publishing original informational texts.', 1, 159),
  ('revised-k10-grade-8-english:standard:performance:period-3:item-1', 'revised-k10-grade-8-english', 3, null, 'performance', 'The learners analyze the style, form, and features of informational texts (opinion editorials, sports, and Science and Technology articles); evaluate informational texts for clarity of meaning, purpose, and target audience; and compose and publish original multimodal informational texts (opinion editorials, sports, and Science and Technology articles) using appropriate forms and structures that represent their meaning, purpose, and target audience.', 1, 159),
  ('revised-k10-grade-8-english:standard:content:period-4:item-1', 'revised-k10-grade-8-english', 4, null, 'content', 'The learners demonstrate their multiliteracies and communicative competence in evaluating informational texts (academic text: expository essays) and transactional texts (letter of inquiry) for clarity of meaning, purpose, and target audience as a foundation for publishing original informational and transactional texts.', 1, 162),
  ('revised-k10-grade-8-english:standard:performance:period-4:item-1', 'revised-k10-grade-8-english', 4, null, 'performance', 'The learners analyze the style, form, and features of informational texts (expository essays) and transactional texts (letter of inquiry); evaluate informational and transactional texts for clarity of meaning, purpose, and target audience; and compose and publish original multimodal informational texts (expository essays) and transactional texts (letter of inquiry) using appropriate forms and structures that represent their meaning, purpose, and target audience.', 1, 162),
  ('revised-k10-grade-8-filipino:standard:content:period-1:item-1', 'revised-k10-grade-8-filipino', 1, null, 'content', 'Naipamamalas ng mga mag-aaral ang kasanayang komunikatibo, pagiging malikhain, at kritikal na pag-unawa at pagsusuri ng mga tekstong pampanitikan sa Panahon ng Propaganda hanggang sa Panahon ng Himagsikan at tekstong impormasyonal (persweysib) para sa pagpapahalaga sa sariling kalinangan, at pagbuo ng mga teksto sa iba’t ibang paraan (multimodal) para sa tiyak na layunin, pagpapakahulugan, at target na babasa o awdiyens.', 1, 133),
  ('revised-k10-grade-8-filipino:standard:performance:period-1:item-1', 'revised-k10-grade-8-filipino', 1, null, 'performance', 'Nakabubuo ng sanaysay sa pamamagitan ng animasyon sa napiling platform na isinasaalang-alang ang mga elemento ng biswal at multimodal na may paglalapat ng kasanayang komunikatibo, at etikal na kasanayan at pananagutan.', 1, 133),
  ('revised-k10-grade-8-filipino:standard:content:period-2:item-1', 'revised-k10-grade-8-filipino', 2, null, 'content', 'Naipamamalas ng mga mag-aaral ang kasanayang komunikatibo, pagiging malikhain, at kritikal na pag-unawa at pagsusuri ng mga tekstong pampanitikan sa Panahon ng Pananakop ng Estados Unidos at tekstong impormasyonal (persweysib) para sa pagpapahalaga sa sariling kalinangan, at pagbuo ng mga teksto sa iba’t ibang paraan para sa tiyak na layunin, pagpapakahulugan, at target na babasa o awdiyens.', 1, 137),
  ('revised-k10-grade-8-filipino:standard:performance:period-2:item-1', 'revised-k10-grade-8-filipino', 2, null, 'performance', 'Nakabubuo ng panimulang paglalapat sa nilalaman ng sanaysay sa pamamagitan ng video o animasyon na isinasaalang-alang ang mga elemento ng biswal at multimodal na may kasanayang komunikatibo, at etikal na kasanayan at pananagutan.', 1, 137),
  ('revised-k10-grade-8-filipino:standard:content:period-3:item-1', 'revised-k10-grade-8-filipino', 3, null, 'content', 'Naipamamalas ng mga mag-aaral ang kasanayang komunikatibo, pagiging malikhain, at kritikal na pag-unawa at pagsusuri ng mga tekstong pampanitikan sa Panahon ng Pananakop ng Hapon at tekstong impormasyonal (persweysib) at editoryal para sa pagpapahalaga sa sariling kalinangan, at pagbuo ng mga teksto sa iba’t ibang paraan (multimodal) para sa tiyak na layunin, pagpapakahulugan, at target na babasa o awdiyens.', 1, 140),
  ('revised-k10-grade-8-filipino:standard:performance:period-3:item-1', 'revised-k10-grade-8-filipino', 3, null, 'performance', 'Nakabubuo ng pinal na sanaysay sa anyong video o animasyon na isinasaalang-alang ang mga elemento ng biswal at multimodal na may paglalapat ng kasanayang komunikatibo at etikal na kasanayan at pananagutan.', 1, 140),
  ('revised-k10-grade-8-filipino:standard:content:period-4:item-1', 'revised-k10-grade-8-filipino', 4, null, 'content', 'Naipamamalas ng mga mag-aaral ang kasanayang komunikatibo, pagiging malikhain, at kritikal na pag-unawa at pagsusuri ng Obra Maestra – Florante at Laura para sa pagpapahalaga sa sariling kalinangan at pagbuo ng mga teksto sa iba’t ibang paraan para sa tiyak na layunin, pagpapakahulugan, at target na babasa o awdiyens.', 1, 144),
  ('revised-k10-grade-8-filipino:standard:performance:period-4:item-1', 'revised-k10-grade-8-filipino', 4, null, 'performance', 'Nakalilikha ang mag-aaral ng spoken poetry na nagtatampok sa Apat na Himagsik ni Balagtas na maiuugnay sa panunumbalik ng Kalinangang Pilipino na isinasaalang-alang ang mga elemento ng biswal at multimodal na may paglalapat ng kasanayang komunikatibo at etikal na kasanayan at pananagutan.', 1, 144),
