  ('revised-k10-grade-9-english:standard:content:period-1:item-1', 'revised-k10-grade-9-english', 1, null, 'content', 'The learners demonstrate their multiliteracies and communicative competence in evaluating Anglo-American literature (poetry, prose, and drama) for clarity of meaning, purpose, and target audience as a foundation for publishing original literary texts that reflect their expanding cultural identity.', 1, 165),
  ('revised-k10-grade-9-english:standard:performance:period-1:item-1', 'revised-k10-grade-9-english', 1, null, 'performance', 'The learners analyze the style, form, and features of Anglo-American literature (poetry, prose, and drama); evaluate literary texts for clarity of meaning, purpose, and target audience; and compose and publish an original multimodal literary text (one-act play) that represents their meaning, purpose, and target audience, and reflects their expanding cultural identity.', 1, 165),
  ('revised-k10-grade-9-english:standard:content:period-2:item-1', 'revised-k10-grade-9-english', 2, null, 'content', 'The learners demonstrate their multiliteracies and communicative competence in evaluating informational texts (argumentative texts) for clarity of meaning, purpose, and target audience as a foundation for publishing original informational texts.', 1, 167),
  ('revised-k10-grade-9-english:standard:performance:period-2:item-1', 'revised-k10-grade-9-english', 2, null, 'performance', 'The learners analyze the style, form, and features of informational texts (argumentative texts); evaluate informational texts for clarity of meaning, purpose, and target audience; and compose and publish original multimodal informational texts (argumentative texts) using appropriate forms and structures that represent their meaning, purpose, and target audience.', 1, 167),
  ('revised-k10-grade-9-english:standard:content:period-3:item-1', 'revised-k10-grade-9-english', 3, null, 'content', 'The learners demonstrate their multiliteracies and communicative competence in evaluating informational texts (argumentative texts) and transactional texts (letter of complaint) for clarity of meaning, purpose, and target audience as a foundation for publishing original informational and transactional texts.', 1, 170),
  ('revised-k10-grade-9-english:standard:performance:period-3:item-1', 'revised-k10-grade-9-english', 3, null, 'performance', 'The learners analyze the style, form, and features of informational texts (argumentative texts) and transactional texts (letter of complaint); evaluate informational and transactional texts for clarity of meaning, purpose, and target audience; and compose and publish original multimodal informational texts (argumentative texts) and transactional texts (letter of complaint) using appropriate forms and structures that represent their meaning, purpose, and target audience.', 1, 170),
  ('revised-k10-grade-9-english:standard:content:period-4:item-1', 'revised-k10-grade-9-english', 4, null, 'content', 'The learners demonstrate their multiliteracies and communicative competence in evaluating informational texts (academic text: literature review) for clarity of meaning, purpose, and target audience as a foundation for publishing original informational texts.', 1, 173),
  ('revised-k10-grade-9-english:standard:performance:period-4:item-1', 'revised-k10-grade-9-english', 4, null, 'performance', 'The learners analyze the style, form, and features of informational texts (literature review); evaluate informational texts for clarity of meaning, purpose, and target audience; and compose and publish original multimodal informational texts (literature review) using appropriate forms and structures that represent their meaning, purpose, and target audience.', 1, 173),
  ('revised-k10-grade-9-filipino:standard:content:period-1:item-1', 'revised-k10-grade-9-filipino', 1, null, 'content', 'Naipamamalas ng mga mag-aaral ang kasanayang komunikatibo, pagiging malikhain, at kritikal na pag-unawa at pagsusuri ng mga tekstong pampanitikan sa Panahon ng Kasarinlan, tekstong impormasyonal (argumentatibo) para sa paghubog ng kamalayang panlipunan at pagbuo ng mga teksto sa iba’t ibang paraan (multimodal) para sa tiyak na layunin, pagpapakahulugan, at target na babasa o awdiyens.', 1, 147),
  ('revised-k10-grade-9-filipino:standard:performance:period-1:item-1', 'revised-k10-grade-9-filipino', 1, null, 'performance', 'Nakabubuo ng isang literaring analisis ng graphic novel na isinasaalang-alang ang mga elementong biswal at multimodal na may paglalapat ng kasanayang komunikatibo at etikal na kasanayan at pananagutan.', 1, 147),
  ('revised-k10-grade-9-filipino:standard:content:period-2:item-1', 'revised-k10-grade-9-filipino', 2, null, 'content', 'Naipamamalas ng mga mag-aaral ang kasanayang komunikatibo, pagiging malikhain, at kritikal na pag-unawa at pagsusuri ng mga tekstong pampanitikan sa Panahon ng Kasarinlan, tekstong impormasyonal (argumentatibo) para sa paghubog ng kamalayang panlipunan at pagbuo ng mga teksto sa iba’t ibang paraan (multimodal) para sa tiyak na layunin, pagpapakahulugan, at target na babasa o awdiyens.', 1, 151),
  ('revised-k10-grade-9-filipino:standard:performance:period-2:item-1', 'revised-k10-grade-9-filipino', 2, null, 'performance', 'Nakabubuo ng isang pabalat ng graphic novel na batay sa isinagawang literaring analisis ng nabasang nobela na isinasaalang-alang ang mga elemento ng biswal at multimodal na may paglalapat ng kasanayang komunikatibo, at etikal na kasanayan at pananagutan.', 1, 151),
  ('revised-k10-grade-9-filipino:standard:content:period-3:item-1', 'revised-k10-grade-9-filipino', 3, null, 'content', 'Naipamamalas ng mga mag-aaral ang kasanayang komunikatibo, pagiging malikhain, at kritikal na pag-unawa at pagsusuri ng mga tekstong pampanitikan mula 1986 hanggang sa pagbubukas ng bagong Milenyo, at tekstong transaksyonal para sa paghubog ng kamalayang panlipunan at pagbuo ng mga teksto sa iba’t ibang paraan (multimodal) para sa tiyak na layunin, pagpapakahulugan, at target na babasa o awdiyens.', 1, 155),
  ('revised-k10-grade-9-filipino:standard:performance:period-3:item-1', 'revised-k10-grade-9-filipino', 3, null, 'performance', 'Nakabubuo ng isang korespondensiya opisyal gamit ang nilikhang logo at letterhead na isinasaalang-alang ang mga elemento ng biswal at multimodal na may paglalapat ng kasanayang komunikatibo, at etikal na kasanayan at pananagutan.', 1, 155),
  ('revised-k10-grade-9-filipino:standard:content:period-4:item-1', 'revised-k10-grade-9-filipino', 4, null, 'content', 'Naipamamalas ng mga mag-aaral ang kasanayang komunikatibo, pagiging malikhain, at kritikal na pag-unawa at pagsusuri ng Obra Maestra – Noli Me Tangere para sa paghubog ng kamalayang panlipunan at pagbuo ng mga teksto sa iba’t ibang paraan (multimodal) para sa tiyak na layunin, pagpapakahulugan, at target na babasa o awdiyens.', 1, 158),
  ('revised-k10-grade-9-filipino:standard:performance:period-4:item-1', 'revised-k10-grade-9-filipino', 4, null, 'performance', 'Nakabubuo ng video trailer ng Noli Me Tangere na naipakikita ang kamalayan sa usaping panlipunan sa Obra Maestra na isinasaalang-alang ang elemento ng biswal at multimodal na may paglalapat ng kasanayang komunikatibo, at etikal na kasanayan at pananagutan.', 1, 158),
