  ('revised-k10-grade-9-values-education:standard:performance:period-4:item-4', 'revised-k10-grade-9-values-education', 4, 'D25', 'performance', 'Naisasagawa ng mag-aaral ang paraan ng pagpapalalim ng ispirituwalidad na gabay sa pagharap sa pagsubok ng buhay upang malinang ang pagiging matatag.', 4, 265),
  ('revised-k10-grade-9-values-education:standard:performance:period-4:item-5', 'revised-k10-grade-9-values-education', 4, 'D26', 'performance', 'Naisasagawa ng mag-aaral ang mga gawaing panrelihiyon na nagsusulong sa pagpapabuti ng kalagayan ng kapuwa bilang tanda ng pakikiisa.', 5, 266),
  ('revised-k10-grade-9-values-education:standard:performance:period-4:item-6', 'revised-k10-grade-9-values-education', 4, 'D27', 'performance', 'Naisasagawa ng mag-aaral ang sariling paraan ng pagsuporta sa adbokasiya ng mga lokal na pangkat na nangangalaga sa kalikasan upang malinang ang pagiging mabuting katiwala.', 6, 267),
  ('revised-k10-grade-9-values-education:standard:performance:period-4:item-7', 'revised-k10-grade-9-values-education', 4, 'D28', 'performance', 'Naisasagawa ng mag-aaral ang sariling paraan ng pagpapaunlad ng gawi sa pagtangkilik sa mga serbisyo, talento, at produktong gawang Pilipino upang malinang ang nasyonalismo.', 7, 268),
  ('revised-k10-kindergarten-kindergarten:standard:content:period-1:item-1', 'revised-k10-kindergarten-kindergarten', 1, null, 'content', 'The learners demonstrate understanding of attitude, emotions, similarities and differences of oneself and others including the concept of family, and of importance of physical health, safety, and appropriate movement concepts.', 1, 18),
  ('revised-k10-kindergarten-kindergarten:standard:performance:period-1:item-1', 'revised-k10-kindergarten-kindergarten', 1, null, 'performance', 'The learners manage emotions, make decisions, recognize similarities and differences of people, and express oneself based on personal experiences; participate actively in various physical activities; use hands in creating models; perform coordinated body movements; and take care of one’s physical health and safety.', 1, 18),
  ('revised-k10-kindergarten-kindergarten:standard:content:period-2:item-1', 'revised-k10-kindergarten-kindergarten', 2, null, 'content', 'The learners understand the value of discipline, honesty, respect, friendship, and care and concern.', 1, 20),
  ('revised-k10-kindergarten-kindergarten:standard:performance:period-2:item-1', 'revised-k10-kindergarten-kindergarten', 2, null, 'performance', 'The learners demonstrate proper discipline, honesty, respect, friendship, and care towards other people.', 1, 20),
  ('revised-k10-kindergarten-kindergarten:standard:content:period-3:item-1', 'revised-k10-kindergarten-kindergarten', 3, null, 'content', 'The learners demonstrate understanding of one’s identity, rights, and responsibilities as a Filipino citizen.', 1, 22),
  ('revised-k10-kindergarten-kindergarten:standard:performance:period-3:item-1', 'revised-k10-kindergarten-kindergarten', 3, null, 'performance', 'The learners show appreciation for one’s culture; understand one’s right as a Filipino citizen; and demonstrate a sense of responsibility as a Filipino citizen.', 1, 22),
  ('revised-k10-kindergarten-kindergarten:standard:content:period-4:item-1', 'revised-k10-kindergarten-kindergarten', 4, null, 'content', 'The learners appreciate the beauty of the environment through creative expressions.', 1, 23),
