  ('sshs-grade-11-agricultural-crops-production:standard:content:period-1:item-1', 'sshs-grade-11-agricultural-crops-production', 1, null, 'content', 'The learners demonstrate understanding of principles on the overview of agricultural crops production, farm tools, implements, and simple equipment, and pre-operative check-up following the manufacturer’s manual.', 1, 2),
