  ('sshs-grade-11-agro-entrepreneurship:standard:content:period-1:item-1', 'sshs-grade-11-agro-entrepreneurship', 1, null, 'content', 'The learners demonstrate an understanding of the principles in Agro-Entrepreneurship and potential market opportunities of farm products and services.', 1, 2),
