  ('sshs-grade-11-agro-entrepreneurship:standard:content:period-4:item-1', 'sshs-grade-11-agro-entrepreneurship', 4, null, 'content', 'The learners demonstrate an understanding on the principles of price monitoring, types of buyers, selling strategies, customer agreement, product delivery process and post-delivery services.', 1, 9),
