  ('sshs-grade-11-animation:standard:performance:period-4:item-1', 'sshs-grade-11-animation', 4, null, 'performance', 'Learners create digital animation output and calculate animation cost based on industry standards.', 1, 5),
  ('sshs-grade-11-aquaculture:standard:content:period-1:item-1', 'sshs-grade-11-aquaculture', 1, null, 'content', 'The learners demonstrate an understanding of the principles of aquaculture, use and maintenance of tools and equipment, and factors in site selection and pond preparation.', 1, 2),
  ('sshs-grade-11-aquaculture:standard:performance:period-1:item-1', 'sshs-grade-11-aquaculture', 1, null, 'performance', 'The learners perform maintaining tools, materials and equipment, site selection and pond preparation appropriate to local industry.', 1, 2),
  ('sshs-grade-11-aquaculture:standard:content:period-2:item-1', 'sshs-grade-11-aquaculture', 2, null, 'content', 'The learners demonstrate an understanding of the principles in designing aquaculture facilities, record keeping, hatchery operations, and broodstock and spawning management.', 1, 4),
  ('sshs-grade-11-aquaculture:standard:performance:period-2:item-1', 'sshs-grade-11-aquaculture', 2, null, 'performance', 'The learners perform management of hatchery, and broodstock and spawning in aquaculture following industry practices.', 1, 4),
  ('sshs-grade-11-aquaculture:standard:content:period-3:item-1', 'sshs-grade-11-aquaculture', 3, null, 'content', 'The learners demonstrate an understanding of the process of stocking aquaculture species, feeding management and stock sampling computations.', 1, 6),
  ('sshs-grade-11-aquaculture:standard:performance:period-3:item-1', 'sshs-grade-11-aquaculture', 3, null, 'performance', 'The learners perform stocking of aquaculture species, feeding management and stock sampling computations.', 1, 6),
  ('sshs-grade-11-aquaculture:standard:content:period-4:item-1', 'sshs-grade-11-aquaculture', 4, null, 'content', 'The learners demonstrate an understanding of the principles of water quality management, health management, harvest and post-harvest activities, and marketing of aquaculture products.', 1, 8),
  ('sshs-grade-11-aquaculture:standard:performance:period-4:item-1', 'sshs-grade-11-aquaculture', 4, null, 'performance', 'The learners perform monitoring of water quality parameters, health management practices, harvest and post-harvest activities, and marketing of aquaculture products.', 1, 8),
  ('sshs-grade-11-arts-1-creative-industries-visual-art-literary-art-media-art-applied-art-and-traditional-art:standard:content:period-1:item-1', 'sshs-grade-11-arts-1-creative-industries-visual-art-literary-art-media-art-applied-art-and-traditional-art', 1, null, 'content', 'The learners demonstrate understanding of the creative industries’ related laws and regulations, practices, applications, and ethical considerations in the local and global contexts of visual, literary, media, applied and/or traditional arts as well as the elements, materials, and techniques, as well as the proper use of materials, tools, equipment, and facilities in production processes.', 1, 2),
  ('sshs-grade-11-arts-1-creative-industries-visual-art-literary-art-media-art-applied-art-and-traditional-art:standard:performance:period-1:item-1', 'sshs-grade-11-arts-1-creative-industries-visual-art-literary-art-media-art-applied-art-and-traditional-art', 1, null, 'performance', 'The learners execute techniques and skills, as well as the proper use of materials, tools, equipment, and facilities in mounting creative works, in reference to the mapped creative industries in their specific communities as defined by relevant laws within the local and global contexts.', 1, 2),
  ('sshs-grade-11-arts-1-creative-industries-visual-art-literary-art-media-art-applied-art-and-traditional-art:standard:content:period-2:item-1', 'sshs-grade-11-arts-1-creative-industries-visual-art-literary-art-media-art-applied-art-and-traditional-art', 2, null, 'content', 'The learners demonstrate understanding of socio-cultural, historical, and economic contexts of production and distribution of various art disciplines emphasizing visual arts, media, applied arts, literary arts, and/or traditional arts, as a basis for art criticism and review of their works, career opportunities, and entrepreneurial pathways.', 1, 6),
  ('sshs-grade-11-arts-1-creative-industries-visual-art-literary-art-media-art-applied-art-and-traditional-art:standard:performance:period-2:item-1', 'sshs-grade-11-arts-1-creative-industries-visual-art-literary-art-media-art-applied-art-and-traditional-art', 2, null, 'performance', 'The learners produce various creative works (from visual arts, media, applied arts, literary arts, and/or traditional arts), highlighting the importance of contexts in their meanings and those that reflect its potential applications and impact as aligned with applicable markets and relevant audiences for public exhibition.', 1, 6),
  ('sshs-grade-11-arts-2-creative-industries-music-dance-and-theater:standard:content:period-1:item-1', 'sshs-grade-11-arts-2-creative-industries-music-dance-and-theater', 1, null, 'content', 'The learner shows understanding of the creative industries’ related laws and regulations, practices, applications, and ethical considerations; elements, materials, and techniques; and the proper use of materials, tools, equipment, and facilities in production processes in the local and global contexts of Music, Dance, and Theater.', 1, 2),
  ('sshs-grade-11-arts-2-creative-industries-music-dance-and-theater:standard:performance:period-1:item-1', 'sshs-grade-11-arts-2-creative-industries-music-dance-and-theater', 1, null, 'performance', 'The learner executes techniques, skills, and proper use of materials, tools, equipment, and facilities in mounting creative works in reference to the mapped creative industries in their specific communities as defined by relevant laws within local and global contexts.', 1, 2),
  ('sshs-grade-11-arts-2-creative-industries-music-dance-and-theater:standard:content:period-2:item-1', 'sshs-grade-11-arts-2-creative-industries-music-dance-and-theater', 2, null, 'content', 'The learner demonstrates understanding of the socio-cultural, historical, and economic context of production; distribution; and consumption of arts as a basis for creating new works, doing art criticism, exploring audiences, exploring career opportunities, and considering entrepreneurial pathways.', 1, 6),
  ('sshs-grade-11-arts-2-creative-industries-music-dance-and-theater:standard:performance:period-2:item-1', 'sshs-grade-11-arts-2-creative-industries-music-dance-and-theater', 2, null, 'performance', 'The learner produces various creative works that highlight the importance of context in their meanings and those that reflect their potential applications and impact', 1, 6),
  ('sshs-grade-11-automotive-servicing-electrical-repair:standard:content:period-1:item-1', 'sshs-grade-11-automotive-servicing-electrical-repair', 1, null, 'content', 'The learners demonstrate an understanding of the concepts and principles in diagnosing, repairing ignition system starting system, charging system and body electrical systems”', 1, 2),
  ('sshs-grade-11-automotive-servicing-electrical-repair:standard:performance:period-1:item-1', 'sshs-grade-11-automotive-servicing-electrical-repair', 1, null, 'performance', 'The learners perform procedures in diagnosing, troubleshooting, and repairing the ignition system, starting system, charging system, body electrical system and costing of services employing appropriate safety precautions', 1, 2),
  ('sshs-grade-11-automotive-servicing-electrical-repair:standard:content:period-2:item-1', 'sshs-grade-11-automotive-servicing-electrical-repair', 2, null, 'content', 'The learners demonstrate an understanding of the concepts and principles in diagnosing, troubleshooting, and repairing manual air-conditioning system', 1, 5),
  ('sshs-grade-11-automotive-servicing-electrical-repair:standard:performance:period-2:item-1', 'sshs-grade-11-automotive-servicing-electrical-repair', 2, null, 'performance', 'The learners perform diagnosing, troubleshooting, and repairing of automotive manual air conditioning system and costing of services employing appropriate safety precautions.', 1, 5),
  ('sshs-grade-11-automotive-servicing-engine-and-chassis-repairs:standard:content:period-1:item-1', 'sshs-grade-11-automotive-servicing-engine-and-chassis-repairs', 1, null, 'content', 'The learners demonstrate an understanding of the concepts, principles and processes of automotive engine repair.', 1, 2),
  ('sshs-grade-11-automotive-servicing-engine-and-chassis-repairs:standard:performance:period-1:item-1', 'sshs-grade-11-automotive-servicing-engine-and-chassis-repairs', 1, null, 'performance', 'The learners perform automotive repair of engine cooling system, lubricating systems, intake and exhaust systems, overhaul mechanical systems, and costing of services employing appropriate safety precautions.', 1, 2),
  ('sshs-grade-11-automotive-servicing-engine-and-chassis-repairs:standard:content:period-2:item-1', 'sshs-grade-11-automotive-servicing-engine-and-chassis-repairs', 2, null, 'content', 'The learners demonstrate an understanding of the concepts, principles and processes of automotive chassis repair.', 1, 5),
  ('sshs-grade-11-automotive-servicing-engine-and-chassis-repairs:standard:performance:period-2:item-1', 'sshs-grade-11-automotive-servicing-engine-and-chassis-repairs', 2, null, 'performance', 'The learners perform automotive repair of drive lines, clutch system, manual transmission/transaxle, differential, brake system, steering system, suspension system and costing of services employing appropriate safety precautions.', 1, 5),
  ('sshs-grade-11-bakery-operations:standard:content:period-1:item-1', 'sshs-grade-11-bakery-operations', 1, null, 'content', 'The learners demonstrate an understanding of the fundamentals of baking bread and other baked products.', 1, 2),
  ('sshs-grade-11-bakery-operations:standard:performance:period-1:item-1', 'sshs-grade-11-bakery-operations', 1, null, 'performance', 'The learners demonstrate fundamental skills in baking breads.', 1, 2),
  ('sshs-grade-11-bakery-operations:standard:content:period-2:item-1', 'sshs-grade-11-bakery-operations', 2, null, 'content', 'The learners demonstrate understanding of pastry products.', 1, 4),
  ('sshs-grade-11-bakery-operations:standard:performance:period-2:item-1', 'sshs-grade-11-bakery-operations', 2, null, 'performance', 'The learners apply skills in preparing pastry products.', 1, 4),
  ('sshs-grade-11-bakery-operations:standard:content:period-3:item-1', 'sshs-grade-11-bakery-operations', 3, null, 'content', 'The learners demonstrate understanding on cake products.', 1, 7),
  ('sshs-grade-11-bakery-operations:standard:performance:period-3:item-1', 'sshs-grade-11-bakery-operations', 3, null, 'performance', 'The learners apply skills in producing cakes and cake products', 1, 7),
  ('sshs-grade-11-bakery-operations:standard:content:period-4:item-1', 'sshs-grade-11-bakery-operations', 4, null, 'content', 'The learners demonstrate understanding o n producing traditional and contemporary petit fours.', 1, 8),
  ('sshs-grade-11-bakery-operations:standard:performance:period-4:item-1', 'sshs-grade-11-bakery-operations', 4, null, 'performance', 'The learners apply the skills in producing traditional and contemporary petit fours.', 1, 8),
  ('sshs-grade-11-biology-1:standard:content:period-1:item-1', 'sshs-grade-11-biology-1', 1, 'D01', 'content', 'the cell theory is significant in explaining the structure and function of all living organisms;', 1, 2),
  ('sshs-grade-11-biology-1:standard:content:period-1:item-2', 'sshs-grade-11-biology-1', 1, 'D01', 'content', 'cells can be classified according to distinguishing structures and functions;', 2, 2),
  ('sshs-grade-11-biology-1:standard:content:period-1:item-3', 'sshs-grade-11-biology-1', 1, 'D01', 'content', 'the cell cycle consists of a series of phases, stages, and events; and', 3, 3),
  ('sshs-grade-11-biology-1:standard:content:period-1:item-4', 'sshs-grade-11-biology-1', 1, null, 'content', 'cells have mechanisms that regulate the transport of substances in and out of the cell.', 4, 3),
  ('sshs-grade-11-biology-1:standard:performance:period-1:item-1', 'sshs-grade-11-biology-1', 1, null, 'performance', 'By the end of the quarter, learners discuss the scientific value of the interconnectedness of living organisms and their environment. They evaluate the significance of cell theory and its development in explaining the structure and function of living organisms. Learners classify cells based on their structures and functions, explain the stages and significance of the cell cycle, and describe the mechanisms of passive and active transport in maintaining homeostasis. They participate in practical activities and create presentations that showcase how these biological principles contribute to growth, repair, reproduction, and the diversity of life.', 1, 3),
  ('sshs-grade-11-biology-1:standard:content:period-2:item-1', 'sshs-grade-11-biology-1', 2, 'D02', 'content', 'all cells require energy, nutrients and removal of wastes;', 1, 4),
  ('sshs-grade-11-biology-1:standard:content:period-2:item-2', 'sshs-grade-11-biology-1', 2, 'D03', 'content', 'photosynthesis is the chemical reaction that transforms light energy into chemical energy; and', 2, 4),
  ('sshs-grade-11-biology-1:standard:content:period-2:item-3', 'sshs-grade-11-biology-1', 2, 'D04', 'content', 'cell respiration is the chemical reaction that converts chemical energy into usable forms of energy.', 3, 4),
  ('sshs-grade-11-biology-1:standard:performance:period-2:item-1', 'sshs-grade-11-biology-1', 2, null, 'performance', 'By the end of the Quarter, learners describe the processes of photosynthesis and cellular respiration and explain how these cellular mechanisms transform energy for life. They describe the role of cell structures in photosynthesis and differentiate the light-dependent and light-independent reactions. Learners describe the stages of cellular respiration, including glycolysis, the citric acid cycle, and the Electron Transport Chain, and explain their role in ATP production for cellular activities. They also participate in experiments to create models and presentations that demonstrate how these processes sustain ecosystem stability and support life functions.', 1, 4),
  ('sshs-grade-11-biology-2:standard:content:period-3:item-1', 'sshs-grade-11-biology-2', 3, 'D01', 'content', 'different types of plant tissue can be identified using a microscope;', 1, 2),
  ('sshs-grade-11-biology-2:standard:content:period-3:item-2', 'sshs-grade-11-biology-2', 3, 'D01', 'content', 'the distinguishing characteristics of tissues of a plant are significant for the structure and function of the plant; and', 2, 2),
  ('sshs-grade-11-biology-2:standard:content:period-3:item-3', 'sshs-grade-11-biology-2', 3, 'D02', 'content', 'the structure of animal tissues is critical to the successful functioning of organs and organ systems.', 3, 2),
  ('sshs-grade-11-biology-2:standard:performance:period-3:item-1', 'sshs-grade-11-biology-2', 3, null, 'performance', 'By the end of the quarter, learners describe the structure and function of plant and animal tissues by explaining how their various types contribute to growth, transport, support, and overall survival. Through diagrams, experiments, or presentations, learners describe how tissue specialization supports the functionality and adaptability of plants and animals in their environments.', 1, 3),
  ('sshs-grade-11-biology-2:standard:content:period-4:item-1', 'sshs-grade-11-biology-2', 4, 'D03', 'content', 'organ systems of plants maintain homeostasis; and', 1, 3),
  ('sshs-grade-11-biology-2:standard:content:period-4:item-2', 'sshs-grade-11-biology-2', 4, null, 'content', 'organ systems in animals maintain homeostasis', 2, 3),
  ('sshs-grade-11-biology-2:standard:performance:period-4:item-1', 'sshs-grade-11-biology-2', 4, null, 'performance', 'By the end of the quarter, learners explain the similarities and differences in the structures and functions of plant and animal organ systems by explaining how these systems contribute to maintaining homeostasis. Learners construct models, draw comparative diagrams, and/or create presentations to explain the interconnected roles of organ systems in supporting life processes and adapting to environmental challenges.', 1, 4),
  ('sshs-grade-11-broadband-installation:standard:content:period-1:item-1', 'sshs-grade-11-broadband-installation', 1, null, 'content', 'The learners demonstrate an understanding of the principles, tools, safety procedures, and technical requirements necessary for the proper installation of mast, guy, and accessories in accordance with industry standards.', 1, 2),
  ('sshs-grade-11-broadband-installation:standard:performance:period-1:item-1', 'sshs-grade-11-broadband-installation', 1, null, 'performance', 'The learners perform mast and cable installation in accordance with technical specifications and industry standards.', 1, 2),
  ('sshs-grade-11-broadband-installation:standard:content:period-2:item-1', 'sshs-grade-11-broadband-installation', 2, null, 'content', 'The learner demonstrates an understanding of the tools, technical specifications, and configuration procedures necessary to install and set up Customer Premises Equipment (CPE) effectively, ensuring optimal functionality and connectivity.', 1, 4),
  ('sshs-grade-11-broadband-installation:standard:performance:period-2:item-1', 'sshs-grade-11-broadband-installation', 2, null, 'performance', 'The learners perform CPE installation and configuration in accordance with technical specifications and industry standards.', 1, 4),
  ('sshs-grade-11-broadband-installation:standard:content:period-3:item-1', 'sshs-grade-11-broadband-installation', 3, null, 'content', 'The learners demonstrate an understanding of the fundamentals of fiber optic broadband network installation, maintenance, and quality assurance.', 1, 5),
  ('sshs-grade-11-broadband-installation:standard:performance:period-3:item-1', 'sshs-grade-11-broadband-installation', 3, null, 'performance', 'The learners perform installation and maintenance of fiber optic networks, achieving high signal quality, low loss, and reliable system operation, while adhering to the industry’s best practices and safety standards.', 1, 5),
  ('sshs-grade-11-broadband-installation:standard:content:period-4:item-1', 'sshs-grade-11-broadband-installation', 4, null, 'content', 'The learners demonstrate an understanding of principles in splicing/joining fibers and installation of protection sleeves using the mechanical method as well as installation of aerial and underground cable support.', 1, 7),
  ('sshs-grade-11-broadband-installation:standard:performance:period-4:item-1', 'sshs-grade-11-broadband-installation', 4, null, 'performance', 'The learners perform splicing/joining fibers and installation of protection sleeves using mechanical method as well as installation of aerial and underground cable support while adhering to the industry’s best practices and safety standards', 1, 7),
  ('sshs-grade-11-business-1-basic-accounting:standard:content:period-1:item-1', 'sshs-grade-11-business-1-basic-accounting', 1, null, 'content', 'The learners demonstrate understanding of the fundamental concepts and principles of accounting and accounting for service business.', 1, 2),
  ('sshs-grade-11-business-1-basic-accounting:standard:performance:period-1:item-1', 'sshs-grade-11-business-1-basic-accounting', 1, null, 'performance', 'The learners analyze key accounting functions and principles relevant to real enterprise operations such as type of business, books of accounts used, and accounting process methodology.', 1, 2),
  ('sshs-grade-11-business-1-basic-accounting:standard:content:period-2:item-1', 'sshs-grade-11-business-1-basic-accounting', 2, null, 'content', 'The learners demonstrate understanding of concepts and principles of accounting for merchandising business.', 1, 4),
  ('sshs-grade-11-business-1-basic-accounting:standard:performance:period-2:item-1', 'sshs-grade-11-business-1-basic-accounting', 2, null, 'performance', 'The learners complete the practice sets following the accounting cycle for merchandising business using the perpetual and the periodic methods.', 1, 4),
  ('sshs-grade-11-business-2-business-finance-and-income-taxation:standard:content:period-1:item-1', 'sshs-grade-11-business-2-business-finance-and-income-taxation', 1, null, 'content', 'Learners demonstrate an understanding of the foundational concepts of finance, including financial management principles, financial system structures, and the roles of financial managers in managing both short-term and long-term funds. They also develop competencies in personal financial management, investment analysis, risk assessment, and the application of sound taxation principles.', 1, 2),
  ('sshs-grade-11-business-2-business-finance-and-income-taxation:standard:performance:period-1:item-1', 'sshs-grade-11-business-2-business-finance-and-income-taxation', 1, null, 'performance', 'Learners prepare a personal financial plan based on one’s financial capacity, including a contingency plan to address identified investment risks.', 1, 2),
  ('sshs-grade-11-business-2-business-finance-and-income-taxation:standard:content:period-2:item-1', 'sshs-grade-11-business-2-business-finance-and-income-taxation', 2, null, 'content', 'The learners demonstrate an understanding of sound principles of taxation and its purpose.', 1, 4),
  ('sshs-grade-11-business-2-business-finance-and-income-taxation:standard:performance:period-2:item-1', 'sshs-grade-11-business-2-business-finance-and-income-taxation', 2, null, 'performance', 'Learners analyze an accomplished BIR form 2316.', 1, 4),
  ('sshs-grade-11-business-3-business-economics:standard:content:period-1:item-1', 'sshs-grade-11-business-3-business-economics', 1, null, 'content', 'The learners demonstrate an understanding of the key concepts, principles, and practices in business economics, and apply this knowledge to formulate strategies and make well-informed decisions within the business environment.', 1, 2),
  ('sshs-grade-11-business-3-business-economics:standard:performance:period-1:item-1', 'sshs-grade-11-business-3-business-economics', 1, null, 'performance', 'Learners propose an appropriate business economics strategy or intervention in addressing a particular economic challenge within a local business setting.', 1, 2),
  ('sshs-grade-11-business-3-business-economics:standard:content:period-2:item-1', 'sshs-grade-11-business-3-business-economics', 2, null, 'content', 'The learners demonstrate an understanding of the socio-economic concerns in the business macroenvironment and their interaction with the attainment of a sustainable economy.', 1, 4),
  ('sshs-grade-11-business-3-business-economics:standard:performance:period-2:item-1', 'sshs-grade-11-business-3-business-economics', 2, null, 'performance', 'Learners develop an innovative and sustainable business solution that addresses a socioeconomic challenge in the community.', 1, 4),
  ('sshs-grade-11-caregiving-adult-care:standard:content:period-1:item-1', 'sshs-grade-11-caregiving-adult-care', 1, null, 'content', 'The learners demonstrate understanding in the career opportunities, occupational health and safety, legal and ethical issues in adult care, therapeutic and non-therapeutic communication, care plan, infection control procedures, standard first aid, and basic life support.', 1, 2),
  ('sshs-grade-11-caregiving-adult-care:standard:performance:period-1:item-1', 'sshs-grade-11-caregiving-adult-care', 1, null, 'performance', 'The learners perform infection control procedures, standard first aid, basic life support in accordance with Philippine National Red Cross and care plan.', 1, 2),
  ('sshs-grade-11-caregiving-adult-care:standard:content:period-2:item-1', 'sshs-grade-11-caregiving-adult-care', 2, null, 'content', 'The learners demonstrate an understanding of the phases of aging process and of importance of taking vital signs.', 1, 5),
  ('sshs-grade-11-caregiving-adult-care:standard:performance:period-2:item-1', 'sshs-grade-11-caregiving-adult-care', 2, null, 'performance', 'The learners perform taking vital signs.', 1, 5),
  ('sshs-grade-11-caregiving-adult-care:standard:content:period-3:item-1', 'sshs-grade-11-caregiving-adult-care', 3, null, 'content', 'The learners demonstrate an understanding of the food pyramid and therapeutic diet, feeding techniques, proper storage and disposal of left-over food, basics of toileting and elimination, bathing techniques, perineal/genital care, oral care procedure and bed making procedure.', 1, 6),
  ('sshs-grade-11-caregiving-adult-care:standard:performance:period-3:item-1', 'sshs-grade-11-caregiving-adult-care', 3, null, 'performance', 'The learners perform feeding techniques, left-over food storage and disposal, basics of toileting and elimination, bathing techniques, perineal/genital care, oral care procedure and bed making procedure.', 1, 6),
  ('sshs-grade-11-caregiving-adult-care:standard:content:period-4:item-1', 'sshs-grade-11-caregiving-adult-care', 4, null, 'content', 'The learners demonstrate an understanding of safe ambulation and transfer techniques, basic wound care techniques, heat/cold therapy techniques, palliative care, and medication administration assistance.', 1, 7),
  ('sshs-grade-11-caregiving-adult-care:standard:performance:period-4:item-1', 'sshs-grade-11-caregiving-adult-care', 4, null, 'performance', 'The learners demonstrate safe ambulation and transfer techniques, basic wound care techniques, heat/cold therapy techniques, and medication administration assistance.', 1, 7),
  ('sshs-grade-11-caregiving-child-care:standard:content:period-1:item-1', 'sshs-grade-11-caregiving-child-care', 1, null, 'content', 'The learners demonstrate understanding in occupational safety and health policies and procedures (OHS), career and business opportunities, therapeutic and non-therapeutic communication, care plan, infection control procedures, standard first aid, and basic life support.', 1, 2),
  ('sshs-grade-11-caregiving-child-care:standard:performance:period-1:item-1', 'sshs-grade-11-caregiving-child-care', 1, null, 'performance', 'The learners perform infection control procedures, standard first aid, and basic life support in accordance with the Philippine National Red Cross.', 1, 2),
  ('sshs-grade-11-caregiving-child-care:standard:content:period-2:item-1', 'sshs-grade-11-caregiving-child-care', 2, null, 'content', 'The learners demonstrate understanding in taking vital signs.', 1, 4),
  ('sshs-grade-11-caregiving-child-care:standard:performance:period-2:item-1', 'sshs-grade-11-caregiving-child-care', 2, null, 'performance', 'The learners perform taking vital signs.', 1, 4),
  ('sshs-grade-11-caregiving-child-care:standard:content:period-3:item-1', 'sshs-grade-11-caregiving-child-care', 3, null, 'content', 'The learners demonstrate understanding in pre-natal and post-natal care, breast feeding techniques and position, new born screening test, common types of vaccines and side effects, different stages of growth and development, bathing procedures, and feeding techniques and sleeping habits.', 1, 5),
  ('sshs-grade-11-caregiving-child-care:standard:performance:period-3:item-1', 'sshs-grade-11-caregiving-child-care', 3, null, 'performance', 'The learners perform bathing and feeding procedures.', 1, 5),
  ('sshs-grade-11-caregiving-child-care:standard:content:period-4:item-1', 'sshs-grade-11-caregiving-child-care', 4, null, 'content', 'The learners demonstrate understanding the different behavioral patterns, common routines and principles of medication administration.', 1, 6),
  ('sshs-grade-11-caregiving-child-care:standard:performance:period-4:item-1', 'sshs-grade-11-caregiving-child-care', 4, null, 'performance', 'The learners perform common routines in child care.', 1, 6),
  ('sshs-grade-11-carpentry:standard:content:period-1:item-1', 'sshs-grade-11-carpentry', 1, null, 'content', 'The learners demonstrate an understanding of the concepts and principles in structural carpentry', 1, 2),
  ('sshs-grade-11-carpentry:standard:performance:period-1:item-1', 'sshs-grade-11-carpentry', 1, null, 'performance', 'The learners perform a batter board set up in structural carpentry with safety practices.', 1, 2),
  ('sshs-grade-11-carpentry:standard:content:period-2:item-1', 'sshs-grade-11-carpentry', 2, null, 'content', 'The learners understand procedures in formworks preparations in rough carpentry.', 1, 4),
  ('sshs-grade-11-carpentry:standard:performance:period-2:item-1', 'sshs-grade-11-carpentry', 2, null, 'performance', 'The learners perform procedures in wooden foundation and column formworks with safety', 1, 4),
  ('sshs-grade-11-carpentry:standard:content:period-3:item-1', 'sshs-grade-11-carpentry', 3, null, 'content', 'The learners demonstrate an understanding of concepts in carpentry', 1, 6),
  ('sshs-grade-11-carpentry:standard:performance:period-3:item-1', 'sshs-grade-11-carpentry', 3, null, 'performance', 'The learners perform procedures for installation of framing works (wall, floor, window and jambs) with safety practices.', 1, 6),
  ('sshs-grade-11-carpentry:standard:content:period-4:item-1', 'sshs-grade-11-carpentry', 4, null, 'content', 'The learners understand the concepts and principles in structural carpentry.', 1, 7),
  ('sshs-grade-11-carpentry:standard:performance:period-4:item-1', 'sshs-grade-11-carpentry', 4, null, 'performance', 'The learners perform construction process for roof, ceiling, and build – in cabinet in structural carpentry with safety practices.', 1, 7),
  ('sshs-grade-11-chemistry-1:standard:content:period-1:item-1', 'sshs-grade-11-chemistry-1', 1, 'D01', 'content', 'accuracy, precision, and appropriate use of standard units of measurement are fundamental to Chemistry;', 1, 2),
  ('sshs-grade-11-chemistry-1:standard:content:period-1:item-2', 'sshs-grade-11-chemistry-1', 1, null, 'content', 'the contributions of Planck, Bohr, and Schrödinger helped in the development of Quantum Theory, which explains the behavior of subatomic particle;', 2, 3),
  ('sshs-grade-11-chemistry-1:standard:content:period-1:item-3', 'sshs-grade-11-chemistry-1', 1, null, 'content', 'electrons of elements are arranged according to different energy levels, subshells, and orbitals based on the quantum mechanical model; and', 3, 3),
  ('sshs-grade-11-chemistry-1:standard:content:period-1:item-4', 'sshs-grade-11-chemistry-1', 1, null, 'content', 'isotopes of elements can be both beneficial and harmful.', 4, 3),
  ('sshs-grade-11-chemistry-1:standard:performance:period-1:item-1', 'sshs-grade-11-chemistry-1', 1, null, 'performance', 'By the end of the quarter, learners make reliable measurements and record data using appropriate laboratory and/or measuring tools. They also apply significant figures, scientific notation, and unit conversion. Using the Quantum Mechanical Model, they describe electrons in levels and write electron configurations for elements. Learners explain what isotopes are and how they may be useful and possibly harmful.', 1, 3),
  ('sshs-grade-11-chemistry-1:standard:content:period-2:item-1', 'sshs-grade-11-chemistry-1', 2, 'D02', 'content', 'the atomic mass of an element can be described as “relative” or “average”;', 1, 4),
  ('sshs-grade-11-chemistry-1:standard:content:period-2:item-2', 'sshs-grade-11-chemistry-1', 2, 'D03', 'content', 'the percentage composition of elements in a compound can be used to determine empirical and molecular formulas;', 2, 4),
  ('sshs-grade-11-chemistry-1:standard:content:period-2:item-3', 'sshs-grade-11-chemistry-1', 2, 'D04', 'content', 'chemical compounds are named using the rules of the International Union of Pure and Applied Chemistry (IUPAC);', 3, 4),
  ('sshs-grade-11-chemistry-1:standard:content:period-2:item-4', 'sshs-grade-11-chemistry-1', 2, 'D05', 'content', 'the chemical formula of a compound is a symbolic representation of its chemical composition; and', 4, 4),
  ('sshs-grade-11-chemistry-1:standard:content:period-2:item-5', 'sshs-grade-11-chemistry-1', 2, 'D05', 'content', 'the properties of chemical compounds depend on the type of bond between the elements in a compound.', 5, 4),
  ('sshs-grade-11-chemistry-1:standard:performance:period-2:item-1', 'sshs-grade-11-chemistry-1', 2, null, 'performance', 'By the end of the quarter, learners explain the difference between relative and average atomic mass, and they correctly name compounds using the IUPAC nomenclature standard. They write formulas particularly for compounds commonly used in everyday life. They differentiate between ionic and covalent bonds and use illustrations and diagrams to explain the Lewis structure of an ionic compound and a covalent compound, applying the octet rule. They write chemical names and formulas for ionic and covalent compounds and describe their properties. Learners predict polarity based on electronegativity and molecular geometry.', 1, 5),
  ('sshs-grade-11-chemistry-2:standard:content:period-3:item-1', 'sshs-grade-11-chemistry-2', 3, 'D01', 'content', 'intermolecular forces, such as hydrogen bonds, influence the physical properties of substances;', 1, 2),
  ('sshs-grade-11-chemistry-2:standard:content:period-3:item-2', 'sshs-grade-11-chemistry-2', 3, null, 'content', 'hydrocarbon and its derivatives play a crucial role in organic reactions and the behavior of organic compounds;', 2, 3),
  ('sshs-grade-11-chemistry-2:standard:content:period-3:item-3', 'sshs-grade-11-chemistry-2', 3, null, 'content', 'there are four major classes of organic compounds called biomolecules: and', 3, 3),
  ('sshs-grade-11-chemistry-2:standard:content:period-3:item-4', 'sshs-grade-11-chemistry-2', 3, null, 'content', 'carbon compounds undergo several types of common chemical reactions.', 4, 3),
  ('sshs-grade-11-chemistry-2:standard:performance:period-3:item-1', 'sshs-grade-11-chemistry-2', 3, null, 'performance', 'By the end of the quarter, learners differentiate intermolecular forces and intramolecular forces on the molecules of liquid water. They explain the significance of the carbon-hydrogen and carbon-carbon bonds and identify the major groups of organic compounds. They write equations for the processes of photosynthesis and respiration. Furthermore, they examine the characteristics of biomolecules and discuss their significance in both biological and everyday contexts.', 1, 3),
  ('sshs-grade-11-chemistry-2:standard:content:period-4:item-1', 'sshs-grade-11-chemistry-2', 4, 'D02', 'content', 'there are 6 main types of chemical reactions, many of which occur naturally in the environment and in living things;', 1, 4),
  ('sshs-grade-11-chemistry-2:standard:content:period-4:item-2', 'sshs-grade-11-chemistry-2', 4, 'D03', 'content', 'the mole is a fundamental unit in chemistry which is used to quantify and relate the mass of substances and to the number of particles that facilitate calculations in chemical reactions; and', 2, 4),
  ('sshs-grade-11-chemistry-2:standard:content:period-4:item-3', 'sshs-grade-11-chemistry-2', 4, 'D04', 'content', 'mass relationships in chemical reactions help to understand how to calculate the amounts of reactants and products involved in chemical reactions observed in daily life activities, environmental science, and industrial processes.', 3, 4),
  ('sshs-grade-11-chemistry-2:standard:performance:period-4:item-1', 'sshs-grade-11-chemistry-2', 4, null, 'performance', 'By the end of the quarter, the learners describe different types of chemical reactions and balance a chemical equation. They explain the relationship between Avogadro’s number and the chemical unit, the mole of any substance. They explain the Law of Conservation of Mass and perform stoichiometric calculations to determine quantities of reactants and products.', 1, 5),
  ('sshs-grade-11-citizenship-and-civic-engagement:standard:content:period-1:item-1', 'sshs-grade-11-citizenship-and-civic-engagement', 1, null, 'content', 'The learners demonstrate an understanding of citizenship, civil society organization, social movements, perspectives of community, community action, and principles of community-action initiatives.', 1, 2),
  ('sshs-grade-11-citizenship-and-civic-engagement:standard:performance:period-1:item-1', 'sshs-grade-11-citizenship-and-civic-engagement', 1, null, 'performance', 'The learners shall be able to develop an advocacy campaign of an empowered and active citizen.', 1, 2),
  ('sshs-grade-11-citizenship-and-civic-engagement:standard:content:period-2:item-1', 'sshs-grade-11-citizenship-and-civic-engagement', 2, null, 'content', 'Learners demonstrate an understanding of the methodologies and approaches to community action and involvement across disciplines, highlighting the principles, strategies, and significance of active community participation in addressing societal issues and promoting sustainable development.', 1, 5),
  ('sshs-grade-11-citizenship-and-civic-engagement:standard:performance:period-2:item-1', 'sshs-grade-11-citizenship-and-civic-engagement', 2, null, 'performance', 'Learners shall be able to develop and implement a community action plan that addresses identified community issues, applying appropriate methodologies and approaches to promote active participation, sustainable development, and positive social change.', 1, 5),
  ('sshs-grade-11-commercial-air-conditioning-installation-and-servicing:standard:content:period-1:item-1', 'sshs-grade-11-commercial-air-conditioning-installation-and-servicing', 1, null, 'content', 'The learner understands the concepts and principles of the Commercial Air-Conditioning unit', 1, 2),
  ('sshs-grade-11-commercial-air-conditioning-installation-and-servicing:standard:performance:period-1:item-1', 'sshs-grade-11-commercial-air-conditioning-installation-and-servicing', 1, null, 'performance', 'The learner performs the installation of the Commercial Air-Conditioning unit with safety precautions.', 1, 2),
  ('sshs-grade-11-commercial-air-conditioning-installation-and-servicing:standard:content:period-2:item-1', 'sshs-grade-11-commercial-air-conditioning-installation-and-servicing', 2, null, 'content', 'The learner understands the concepts and principles of the Commercial Air-Conditioning unit', 1, 4),
  ('sshs-grade-11-commercial-air-conditioning-installation-and-servicing:standard:performance:period-2:item-1', 'sshs-grade-11-commercial-air-conditioning-installation-and-servicing', 2, null, 'performance', 'The learner performs maintenance, troubleshooting, and commissioning Commercial Air-Conditioning units with safety precautions.', 1, 4),
  ('sshs-grade-11-computer-programming-java:standard:content:period-1:item-1', 'sshs-grade-11-computer-programming-java', 1, null, 'content', 'The learners demonstrate an understanding of Java programming, including basic structure, syntax, data types, variables, and comments. They also develop skills in creating algorithms, flowcharts, and pseudocode to plan and visualize their code before implementation.', 1, 2),
  ('sshs-grade-11-computer-programming-java:standard:performance:period-1:item-1', 'sshs-grade-11-computer-programming-java', 1, null, 'performance', 'The learners perform procedures in setting up the Integrated Development Environment (IDE) and in creating algorithms, flowcharts, and pseudocode to plan and visualize their code.', 1, 2),
  ('sshs-grade-11-computer-programming-java:standard:content:period-2:item-1', 'sshs-grade-11-computer-programming-java', 2, null, 'content', 'The learners demonstrate an understanding of Java Operators, Input/Output (I/O) classes, flow control structures, and arrays to solve real-world problems.', 1, 4),
  ('sshs-grade-11-computer-programming-java:standard:performance:period-2:item-1', 'sshs-grade-11-computer-programming-java', 2, null, 'performance', 'The learners create a well-structured program using Java Operators, input and output classes, flow control structures, and arrays.', 1, 4),
  ('sshs-grade-11-computer-programming-java:standard:content:period-3:item-1', 'sshs-grade-11-computer-programming-java', 3, null, 'content', 'The learners demonstrate an understanding of object-oriented Java programming principles, procedures to manage errors with exception handling, and the Java Collections Framework for efficient data management.', 1, 5),
  ('sshs-grade-11-computer-programming-java:standard:performance:period-3:item-1', 'sshs-grade-11-computer-programming-java', 3, null, 'performance', 'The learners create a well-structured and efficient program using Java flow control structures, Java arrays, and Java Object-Oriented Programming (OOP) language.', 1, 5),
  ('sshs-grade-11-computer-programming-java:standard:content:period-4:item-1', 'sshs-grade-11-computer-programming-java', 4, null, 'content', 'The learners showcase their grasp of Java’s multithreading principles, graphical user interface (GUI) development, and efficient component structuring to build interactive and responsive applications. They incorporate market analysis to ensure their solutions meet industry demands and customer needs.', 1, 6),
  ('sshs-grade-11-computer-programming-java:standard:performance:period-4:item-1', 'sshs-grade-11-computer-programming-java', 4, null, 'performance', 'The learners will develop a creative GUI-based Java application that demonstrates innovative solutions to real-world problems.', 1, 6),
  ('sshs-grade-11-computer-programming-net-technology:standard:content:period-1:item-1', 'sshs-grade-11-computer-programming-net-technology', 1, null, 'content', 'The learners demonstrate an understanding of fundamental concepts and principles of syntax and elements in Hyper Text Mark-Up Language (HTML) and the properties and values used in Cascading Style Sheet (CSS) in developing and designing a website.', 1, 2),
  ('sshs-grade-11-computer-programming-net-technology:standard:performance:period-1:item-1', 'sshs-grade-11-computer-programming-net-technology', 1, null, 'performance', 'The learners create a web portfolio using Hyper Text Mark-Up Language (HTML).', 1, 2),
  ('sshs-grade-11-computer-programming-net-technology:standard:content:period-2:item-1', 'sshs-grade-11-computer-programming-net-technology', 2, null, 'content', 'The learners demonstrate an understanding of fundamental principles, syntax, and the properties and values of Cascading Style Sheet (CSS) rule in designing and developing interactive webpages.', 1, 4),
  ('sshs-grade-11-computer-programming-net-technology:standard:performance:period-2:item-1', 'sshs-grade-11-computer-programming-net-technology', 2, null, 'performance', 'The learners create a web portfolio applying Cascading Style Sheet (CSS) rules.', 1, 4),
  ('sshs-grade-11-computer-programming-net-technology:standard:content:period-3:item-1', 'sshs-grade-11-computer-programming-net-technology', 3, null, 'content', 'Demonstrate an understanding of the principles of web responsive development by using JavaScript functions and C# programming language.', 1, 5),
  ('sshs-grade-11-computer-programming-net-technology:standard:performance:period-3:item-1', 'sshs-grade-11-computer-programming-net-technology', 3, null, 'performance', 'The learners create a web application project using JavaScript and C# programming language.', 1, 5),
  ('sshs-grade-11-computer-programming-net-technology:standard:content:period-4:item-1', 'sshs-grade-11-computer-programming-net-technology', 4, null, 'content', 'Demonstrate an understanding of the principles of responsive web development by exploring features of ASP.NET Model View Controller architecture and back-end database, conversion of web to mobile application, and computation of service costing.', 1, 7),
  ('sshs-grade-11-computer-programming-net-technology:standard:performance:period-4:item-1', 'sshs-grade-11-computer-programming-net-technology', 4, null, 'performance', 'The learners create a web application following the procedures of managing the list of tasks of Creating, Reading, Updating, and Deleting (CRUD) operations with a database backend, conversion of web to mobile application, and computation of service costing.', 1, 7),
  ('sshs-grade-11-computer-programming-oracle-database:standard:content:period-1:item-1', 'sshs-grade-11-computer-programming-oracle-database', 1, null, 'content', 'The learners demonstrate an understanding of concepts and components of database management systems and use of SQL basic syntax for data manipulation.', 1, 2),
  ('sshs-grade-11-computer-programming-oracle-database:standard:performance:period-1:item-1', 'sshs-grade-11-computer-programming-oracle-database', 1, null, 'performance', 'The learners execute basic SQL syntax for data manipulation.', 1, 2),
  ('sshs-grade-11-computer-programming-oracle-database:standard:content:period-2:item-1', 'sshs-grade-11-computer-programming-oracle-database', 2, null, 'content', 'The learners demonstrate an understanding of multiple row functions, joins, subqueries, and substitution variables to retrieve and display data from multiple tables.', 1, 5),
  ('sshs-grade-11-computer-programming-oracle-database:standard:performance:period-2:item-1', 'sshs-grade-11-computer-programming-oracle-database', 2, null, 'performance', 'The learners create a database applying multiple row functions, joins, subqueries, and substitution variables to retrieve and display data from multiple tables.', 1, 5),
  ('sshs-grade-11-computer-programming-oracle-database:standard:content:period-3:item-1', 'sshs-grade-11-computer-programming-oracle-database', 3, null, 'content', 'The learners demonstrate an understanding of Data Manipulation Language (DML) commands in creating and managing database using constraints, views, database objects, managing user access roles and set operators to combine query results.', 1, 8),
  ('sshs-grade-11-computer-programming-oracle-database:standard:performance:period-3:item-1', 'sshs-grade-11-computer-programming-oracle-database', 3, null, 'performance', 'The learners apply DML commands in creating and managing database using constraints, views, database objects, managing user access roles and set operators to combine query results.', 1, 8),
  ('sshs-grade-11-computer-programming-oracle-database:standard:content:period-4:item-1', 'sshs-grade-11-computer-programming-oracle-database', 4, null, 'content', 'The learners demonstrate an understanding in connecting programming language (PL) to a SQL database, effectively performing Create, Read, Update and Delete (CRUD) operations.', 1, 12),
  ('sshs-grade-11-computer-programming-oracle-database:standard:performance:period-4:item-1', 'sshs-grade-11-computer-programming-oracle-database', 4, null, 'performance', 'The learners create an application by connecting programming language (PL) to a SQL database, effectively performing Create, Read, Update and Delete (CRUD) operations.', 1, 12),
  ('sshs-grade-11-computer-systems-servicing:standard:content:period-1:item-1', 'sshs-grade-11-computer-systems-servicing', 1, null, 'content', 'The learners demonstrate an understanding of concepts and principles in setting up computer systems.', 1, 2),
  ('sshs-grade-11-computer-systems-servicing:standard:performance:period-1:item-1', 'sshs-grade-11-computer-systems-servicing', 1, null, 'performance', 'The learners perform setting up computer systems, adhering to occupational health and safety standards.', 1, 2),
  ('sshs-grade-11-computer-systems-servicing:standard:content:period-2:item-1', 'sshs-grade-11-computer-systems-servicing', 2, null, 'content', 'The learners demonstrate an understanding of the principles of setting up a computer network.', 1, 4),
  ('sshs-grade-11-computer-systems-servicing:standard:performance:period-2:item-1', 'sshs-grade-11-computer-systems-servicing', 2, null, 'performance', 'The learners perform installation, configuration and testing of computer networks, adhering to ooccupational health and safety standards', 1, 4),
  ('sshs-grade-11-computer-systems-servicing:standard:content:period-3:item-1', 'sshs-grade-11-computer-systems-servicing', 3, null, 'content', 'The learners demonstrate an understanding of principles in setting up computer servers.', 1, 5),
  ('sshs-grade-11-computer-systems-servicing:standard:performance:period-3:item-1', 'sshs-grade-11-computer-systems-servicing', 3, null, 'performance', 'The learners perform setting up of a computer server.', 1, 5),
  ('sshs-grade-11-computer-systems-servicing:standard:content:period-4:item-1', 'sshs-grade-11-computer-systems-servicing', 4, null, 'content', 'The learners demonstrate an understanding of the principles of troubleshooting, repairing and maintaining computer systems, network and servers', 1, 7),
  ('sshs-grade-11-computer-systems-servicing:standard:performance:period-4:item-1', 'sshs-grade-11-computer-systems-servicing', 4, null, 'performance', 'The learners perform the process of troubleshooting, repairing and maintaining computer systems, networks and servers.', 1, 7),
  ('sshs-grade-11-construction-operation:standard:content:period-1:item-1', 'sshs-grade-11-construction-operation', 1, null, 'content', 'The learners demonstrate an understanding of concepts and principles in masonry.', 1, 2),
  ('sshs-grade-11-construction-operation:standard:performance:period-1:item-1', 'sshs-grade-11-construction-operation', 1, null, 'performance', 'The learners perform masonry works based on industry and safety standards.', 1, 2),
  ('sshs-grade-11-construction-operation:standard:content:period-2:item-1', 'sshs-grade-11-construction-operation', 2, null, 'content', 'The learners demonstrate an understanding of concepts and principles in performing masonry works.', 1, 4),
  ('sshs-grade-11-construction-operation:standard:performance:period-2:item-1', 'sshs-grade-11-construction-operation', 2, null, 'performance', 'The learners perform masonry works based on industry and safety standards.', 1, 4),
  ('sshs-grade-11-construction-operation:standard:content:period-3:item-1', 'sshs-grade-11-construction-operation', 3, null, 'content', 'The learners demonstrate an understanding of concepts and principles in performing plumbing works.', 1, 6),
  ('sshs-grade-11-construction-operation:standard:performance:period-3:item-1', 'sshs-grade-11-construction-operation', 3, null, 'performance', 'The learners perform plumbing works based on industry and safety standards.', 1, 6),
  ('sshs-grade-11-construction-operation:standard:content:period-4:item-1', 'sshs-grade-11-construction-operation', 4, null, 'content', 'The learners demonstrate an understanding of concepts and principles in basic construction management.', 1, 8),
  ('sshs-grade-11-construction-operation:standard:performance:period-4:item-1', 'sshs-grade-11-construction-operation', 4, null, 'performance', 'The learners perform project cost and estimates for basic construction services.', 1, 8),
  ('sshs-grade-11-contact-center-services:standard:content:period-1:item-1', 'sshs-grade-11-contact-center-services', 1, null, 'content', 'The learners demonstrate understanding of the principles, processes, tools, and equipment integral to the contact center industry.', 1, 2),
  ('sshs-grade-11-contact-center-services:standard:performance:period-1:item-1', 'sshs-grade-11-contact-center-services', 1, null, 'performance', 'The learners apply industry knowledge of contact center operations, including key terminologies, tools, equipment, and their practical applications in delivering efficient and high-quality customer service.', 1, 2),
  ('sshs-grade-11-contact-center-services:standard:content:period-2:item-1', 'sshs-grade-11-contact-center-services', 2, null, 'content', 'The learners demonstrate an understanding of common cultural variables affecting communication and effective communication skills.', 1, 5),
  ('sshs-grade-11-contact-center-services:standard:performance:period-2:item-1', 'sshs-grade-11-contact-center-services', 2, null, 'performance', 'The learners perform effective voice control with appropriate rate, volume, pitch, and tone to ensure clear and professional communication.', 1, 5),
  ('sshs-grade-11-contact-center-services:standard:content:period-3:item-1', 'sshs-grade-11-contact-center-services', 3, null, 'content', 'The learners demonstrate understanding of the fundamental concepts, processes, and best practices in handling product services and market, inbound and outbound call management customer service settings.', 1, 7),
  ('sshs-grade-11-contact-center-services:standard:performance:period-3:item-1', 'sshs-grade-11-contact-center-services', 3, null, 'performance', 'The learners perform inbound and outbound call management, as well as call procedures.', 1, 7),
  ('sshs-grade-11-contact-center-services:standard:content:period-4:item-1', 'sshs-grade-11-contact-center-services', 4, null, 'content', 'The learners demonstrate understanding of the fundamental concepts, processes, and best practices in handling product services and market for non-voice customer service settings.', 1, 8),
  ('sshs-grade-11-contact-center-services:standard:performance:period-4:item-1', 'sshs-grade-11-contact-center-services', 4, null, 'performance', 'The learners perform non-voice services and procedures.', 1, 8),
  ('sshs-grade-11-contemporary-literature-1:standard:content:period-1:item-1', 'sshs-grade-11-contemporary-literature-1', 1, null, 'content', 'The learner understands literature as a personal and reflective experience that allows the reader, listener or viewer to connect with themselves and others through diverse literary forms and themes.', 1, 3),
  ('sshs-grade-11-contemporary-literature-1:standard:performance:period-1:item-1', 'sshs-grade-11-contemporary-literature-1', 1, null, 'performance', 'The learner demonstrates understanding and appreciation of literature by reflecting on and responding to literary texts, including poetry, in ways that show emotional resonance, cultural awareness, and personal connection.', 1, 3),
  ('sshs-grade-11-contemporary-literature-1:standard:content:period-2:item-1', 'sshs-grade-11-contemporary-literature-1', 2, null, 'content', 'The learner understands literature as a product of cultural and social contexts, and how it continues to shape and reflect contemporary realities and conversations.', 1, 4),
  ('sshs-grade-11-contemporary-literature-1:standard:performance:period-2:item-1', 'sshs-grade-11-contemporary-literature-1', 2, null, 'performance', 'The learner demonstrates understanding and appreciation of literature by interpreting and responding to texts, including short stories or a novella, through their relevance to social issues, cultural identities, and enduring human experiences, expressed through thoughtful observations and collaborative conversations.', 1, 4),
  ('sshs-grade-11-contemporary-literature-2:standard:content:period-1:item-1', 'sshs-grade-11-contemporary-literature-2', 1, null, 'content', 'The learner understands literature as a conversation across time, culture, and form, where texts are adapted and reinterpreted to reflect changing values, audiences, and mediums.', 1, 3),
  ('sshs-grade-11-contemporary-literature-2:standard:performance:period-1:item-1', 'sshs-grade-11-contemporary-literature-2', 1, null, 'performance', 'The learner demonstrates understanding and appreciation of literature by analyzing and producing responses to adaptations, remixes, and reinterpretations of texts, including film or TV series, that reflect dynamic cultural and textual conversations.', 1, 3),
  ('sshs-grade-11-contemporary-literature-2:standard:content:period-2:item-1', 'sshs-grade-11-contemporary-literature-2', 2, null, 'content', 'The learner understands literature as a dynamic and evolving form of human expression that innovates through emerging digital platforms and experimental formats to reflect future possibilities and ongoing transformations in society and self.', 1, 4),
  ('sshs-grade-11-contemporary-literature-2:standard:performance:period-2:item-1', 'sshs-grade-11-contemporary-literature-2', 2, null, 'performance', 'The learner demonstrates understanding and appreciation of literature by engaging with and producing thoughtful and innovative responses to digital and experimental literary texts, showcasing creativity, interactivity, and forward-thinking interpretation.', 1, 4),
  ('sshs-grade-11-contemporary-marketing:standard:content:period-1:item-1', 'sshs-grade-11-contemporary-marketing', 1, null, 'content', 'The learners demonstrate understanding of the fundamental marketing principles of both traditional and contemporary approaches.', 1, 2),
  ('sshs-grade-11-contemporary-marketing:standard:performance:period-1:item-1', 'sshs-grade-11-contemporary-marketing', 1, null, 'performance', 'Learners conduct a market analysis and apply customer-centric strategies to analyze consumer behavior, assess market opportunities, and create a targeted marketing strategy with a unique selling proposition.', 1, 2),
  ('sshs-grade-11-contemporary-marketing:standard:content:period-2:item-1', 'sshs-grade-11-contemporary-marketing', 2, null, 'content', 'The learners demonstrate an understanding of how to integrate digital marketing tools into the 7Ps of the marketing mix, utilize marketing analytics for data-driven decision-making, practice sustainable and ethical marketing, and comprehend the marketing planning process.', 1, 3),
  ('sshs-grade-11-contemporary-marketing:standard:performance:period-2:item-1', 'sshs-grade-11-contemporary-marketing', 2, null, 'performance', 'Learners present a marketing plan for a business, integrating digital tools, the 7Ps of the marketing mix, analytics, and sustainable practices.', 1, 3),
  ('sshs-grade-11-creative-composition-1:standard:content:period-1:item-1', 'sshs-grade-11-creative-composition-1', 1, null, 'content', 'The learner demonstrates understanding of personal creative nonfiction forms, structures, and elements to narrate lived experiences with authenticity and voice.', 1, 2),
  ('sshs-grade-11-creative-composition-1:standard:performance:period-1:item-1', 'sshs-grade-11-creative-composition-1', 1, null, 'performance', 'The learner composes, refines, and publishes a personal nonfiction narrative through a recursive composition process that incorporates feedback, reflection, and revision to express lived experience with authenticity, insight, and narrative technique.', 1, 2),
  ('sshs-grade-11-creative-composition-1:standard:content:period-2:item-1', 'sshs-grade-11-creative-composition-1', 2, null, 'content', 'The learner demonstrates deep understanding of poetic elements, structures, and devices; explores how form, imagery, sound, and language to make meaning, convey emotion, and express self in poetry.', 1, 3),
  ('sshs-grade-11-creative-composition-1:standard:performance:period-2:item-1', 'sshs-grade-11-creative-composition-1', 2, null, 'performance', 'The learner composes, revises, and publishes original poems through a sustained composition process, experimenting with form, sound, and voice to create emotionally resonant poetry, culminating in creative presentation across media formats.', 1, 3),
  ('sshs-grade-11-creative-composition-2:standard:content:period-1:item-1', 'sshs-grade-11-creative-composition-2', 1, null, 'content', 'The learner demonstrates understanding of the narrative structures and techniques of creative fiction, including character development, plot structure, setting, and the use of language to build story and theme.', 1, 2),
  ('sshs-grade-11-creative-composition-2:standard:performance:period-1:item-1', 'sshs-grade-11-creative-composition-2', 1, null, 'performance', 'The learner creates, refines and publishes original short fiction through an iterative process of planning, drafting, and revising, demonstrating imaginative storytelling, character depth, and coherent narrative structure.', 1, 2),
  ('sshs-grade-11-creative-composition-2:standard:content:period-2:item-1', 'sshs-grade-11-creative-composition-2', 2, null, 'content', 'The learner demonstrates understanding of the forms and conventions of public creative nonfiction, and how facts, research, and narrative techniques are woven together to inform, engage, and influence audiences.', 1, 3),
  ('sshs-grade-11-creative-composition-2:standard:performance:period-2:item-1', 'sshs-grade-11-creative-composition-2', 2, null, 'performance', 'The learner composes, revises, and publishes public-facing creative nonfiction through research, drafting, and ethical revision, balancing personal voice and factual accuracy to inform, engage, or advocate, using appropriate platforms, for wider audiences.', 1, 3),
  ('sshs-grade-11-domestic-refrigeration-and-air-conditioning-servicing:standard:content:period-1:item-1', 'sshs-grade-11-domestic-refrigeration-and-air-conditioning-servicing', 1, null, 'content', 'The learner understands the concepts and principles of installing domestic refrigeration and air-conditioning units.', 1, 2),
  ('sshs-grade-11-domestic-refrigeration-and-air-conditioning-servicing:standard:performance:period-1:item-1', 'sshs-grade-11-domestic-refrigeration-and-air-conditioning-servicing', 1, null, 'performance', 'The learner performs the installation of domestic refrigeration and air-conditioning units with safety precautions', 1, 2),
  ('sshs-grade-11-domestic-refrigeration-and-air-conditioning-servicing:standard:content:period-2:item-1', 'sshs-grade-11-domestic-refrigeration-and-air-conditioning-servicing', 2, null, 'content', 'The learner understands the concepts and principles of maintaining domestic refrigeration and window-type air-conditioning units.', 1, 5),
  ('sshs-grade-11-domestic-refrigeration-and-air-conditioning-servicing:standard:performance:period-2:item-1', 'sshs-grade-11-domestic-refrigeration-and-air-conditioning-servicing', 2, null, 'performance', 'The learner performs the maintenance of domestic refrigeration and window-type air-conditioning units with safety precautions', 1, 5),
  ('sshs-grade-11-domestic-refrigeration-and-air-conditioning-servicing:standard:content:period-3:item-1', 'sshs-grade-11-domestic-refrigeration-and-air-conditioning-servicing', 3, null, 'content', 'The learner understands the concepts and principles of troubleshooting domestic refrigeration and window-type air-conditioning units.', 1, 6),
  ('sshs-grade-11-domestic-refrigeration-and-air-conditioning-servicing:standard:performance:period-3:item-1', 'sshs-grade-11-domestic-refrigeration-and-air-conditioning-servicing', 3, null, 'performance', 'The learner performs troubleshooting of domestic refrigeration and window-type air-conditioning units with safety precautions.', 1, 6),
  ('sshs-grade-11-domestic-refrigeration-and-air-conditioning-servicing:standard:content:period-4:item-1', 'sshs-grade-11-domestic-refrigeration-and-air-conditioning-servicing', 4, null, 'content', 'The learner understands the concepts and principles of repairing domestic refrigeration and window-type air-conditioning units.', 1, 7),
  ('sshs-grade-11-domestic-refrigeration-and-air-conditioning-servicing:standard:performance:period-4:item-1', 'sshs-grade-11-domestic-refrigeration-and-air-conditioning-servicing', 4, null, 'performance', 'The learner performs repairing domestic refrigeration and window-type air-conditioning units with safety precautions.', 1, 7),
  ('sshs-grade-11-driving-and-automotive-servicing:standard:content:period-1:item-1', 'sshs-grade-11-driving-and-automotive-servicing', 1, null, 'content', 'The learners demonstrate an understanding of the concepts and principles of driving a light vehicle.', 1, 2),
  ('sshs-grade-11-driving-and-automotive-servicing:standard:performance:period-1:item-1', 'sshs-grade-11-driving-and-automotive-servicing', 1, null, 'performance', 'The learners perform procedures for moving and positioning vehicles, operating vehicle lifting and support equipment, and driving light vehicles, employing appropriate safety precautions.', 1, 2),
  ('sshs-grade-11-driving-and-automotive-servicing:standard:content:period-2:item-1', 'sshs-grade-11-driving-and-automotive-servicing', 2, null, 'content', 'The learners demonstrate an understanding of the concepts and principles of pre-delivery inspection (PDI) in automotive servicing.', 1, 4),
  ('sshs-grade-11-driving-and-automotive-servicing:standard:performance:period-2:item-1', 'sshs-grade-11-driving-and-automotive-servicing', 2, null, 'performance', 'The learners perform procedures of pre-delivery inspection in automotive servicing employing appropriate safety precautions.', 1, 4),
  ('sshs-grade-11-driving-and-automotive-servicing:standard:content:period-3:item-1', 'sshs-grade-11-driving-and-automotive-servicing', 3, null, 'content', 'The learners demonstrate an understanding of the concepts and principles of periodic maintenance services (PMS) for vehicle component parts (engine) in automotive servicing.', 1, 6),
  ('sshs-grade-11-driving-and-automotive-servicing:standard:performance:period-3:item-1', 'sshs-grade-11-driving-and-automotive-servicing', 3, null, 'performance', 'The learners perform procedures of periodic maintenance services (PMS) for vehicle component parts (engine) in automotive servicing, employing appropriate safety precautions.', 1, 6),
  ('sshs-grade-11-driving-and-automotive-servicing:standard:content:period-4:item-1', 'sshs-grade-11-driving-and-automotive-servicing', 4, null, 'content', 'The learners demonstrate an understanding of the concepts of automotive periodic maintenance services (PMS) for the vehicle''s component parts (drive train, brake system, suspension system, and steering system).', 1, 7),
  ('sshs-grade-11-driving-and-automotive-servicing:standard:performance:period-4:item-1', 'sshs-grade-11-driving-and-automotive-servicing', 4, null, 'performance', 'The learners perform automotive periodic maintenance services (PMS) for the vehicle component parts (drive train, brake system, suspension system, and steering system) by employing appropriate safety precautions and conduct vehicle release and service cost calculations.', 1, 7),
  ('sshs-grade-11-earth-and-space-science-1:standard:content:period-1:item-1', 'sshs-grade-11-earth-and-space-science-1', 1, 'D01', 'content', 'the objects making up the universe have distinct characteristics;', 1, 2),
  ('sshs-grade-11-earth-and-space-science-1:standard:content:period-1:item-2', 'sshs-grade-11-earth-and-space-science-1', 1, 'D01', 'content', 'the interactions of the Sun, planets, and moon produce dynamic physical influences;', 2, 2),
  ('sshs-grade-11-earth-and-space-science-1:standard:content:period-1:item-3', 'sshs-grade-11-earth-and-space-science-1', 1, 'D02', 'content', 'the Earth is the only planet in the solar system that supports life;', 3, 2),
  ('sshs-grade-11-earth-and-space-science-1:standard:content:period-1:item-4', 'sshs-grade-11-earth-and-space-science-1', 1, 'D02', 'content', 'the Earth''s position in the solar system contributes to its structure and dynamic nature;', 4, 2),
  ('sshs-grade-11-earth-and-space-science-1:standard:content:period-1:item-5', 'sshs-grade-11-earth-and-space-science-1', 1, null, 'content', 'historical and contemporary models and theories provide the scientific bases for explaining the Earth’s origin, its plates, and boundaries;', 5, 3),
  ('sshs-grade-11-earth-and-space-science-1:standard:content:period-1:item-6', 'sshs-grade-11-earth-and-space-science-1', 1, null, 'content', 'seismic waves and their effects help to explain and understand the nature and composition of the Earth.', 6, 3),
  ('sshs-grade-11-earth-and-space-science-1:standard:performance:period-1:item-1', 'sshs-grade-11-earth-and-space-science-1', 1, null, 'performance', 'By the end of the quarter, learners describe the origin of the solar system and Earth’s historical evolution. They relate Earth’s unique position in the solar system to its composition, structure, and the dynamic nature of its outer layers. Learners explain how scientists determine the nature of Earth''s interior. They also collaboratively create detailed models and scientific analyses and use evidence-based findings to illustrate the nature and composition of the Earth.', 1, 3),
  ('sshs-grade-11-earth-and-space-science-1:standard:content:period-2:item-1', 'sshs-grade-11-earth-and-space-science-1', 2, 'D03', 'content', 'minerals are essential for industrial development, economic growth, and technological advancement, but should be managed sustainably;', 1, 4),
  ('sshs-grade-11-earth-and-space-science-1:standard:content:period-2:item-2', 'sshs-grade-11-earth-and-space-science-1', 2, 'D04', 'content', 'the rock cycle is a dynamic system that forms, alters, and reforms rocks over geological time;', 2, 4),
  ('sshs-grade-11-earth-and-space-science-1:standard:content:period-2:item-3', 'sshs-grade-11-earth-and-space-science-1', 2, 'D04', 'content', 'various environmental factors influence the characteristics of soil;', 3, 4),
  ('sshs-grade-11-earth-and-space-science-1:standard:content:period-2:item-4', 'sshs-grade-11-earth-and-space-science-1', 2, 'D05', 'content', 'the differences between renewable and non-renewable energy sources are key to making sustainable energy choices and reducing environmental impacts; and', 4, 4),
  ('sshs-grade-11-earth-and-space-science-1:standard:content:period-2:item-5', 'sshs-grade-11-earth-and-space-science-1', 2, 'D05', 'content', 'conserving energy sources and promoting sustainable practices are key to economic and environmental sustainability.', 5, 4),
  ('sshs-grade-11-earth-and-space-science-1:standard:performance:period-2:item-1', 'sshs-grade-11-earth-and-space-science-1', 2, null, 'performance', 'By the end of the quarter, learners identify, describe, and classify a range of minerals, rocks, and soils using appropriate scientific techniques. They explain the formation and economic significance of the Philippines’ earth materials and energy sources, emphasizing the importance of sustainable mineral resource management. Learners differentiate renewable and non-renewable energy sources and develop campaigns focused on energy conservation and sustainability.', 1, 5),
  ('sshs-grade-11-earth-and-space-science-2:standard:content:period-3:item-1', 'sshs-grade-11-earth-and-space-science-2', 3, 'D01', 'content', 'a range of theories have contributed to modern understanding of the dynamic nature of Earth’s lithosphere;', 1, 2),
  ('sshs-grade-11-earth-and-space-science-2:standard:content:period-3:item-2', 'sshs-grade-11-earth-and-space-science-2', 3, 'D02', 'content', 'tectonic plates and their movements are responsible for the current shape of the Earth’s lithosphere, and cause geologic phenomena including earthquakes and volcanic activities along the plate boundaries;', 2, 2),
  ('sshs-grade-11-earth-and-space-science-2:standard:content:period-3:item-3', 'sshs-grade-11-earth-and-space-science-2', 3, 'D02', 'content', 'geologic phenomena due to plate tectonics cause sudden movement of rock materials below the Earth’s surface;', 3, 2),
  ('sshs-grade-11-earth-and-space-science-2:standard:content:period-3:item-4', 'sshs-grade-11-earth-and-space-science-2', 3, 'D02', 'content', 'geologic phenomena due to plate tectonics—volcanism is a natural process; and', 4, 3),
  ('sshs-grade-11-earth-and-space-science-2:standard:content:period-3:item-5', 'sshs-grade-11-earth-and-space-science-2', 3, null, 'content', 'weathering, erosion, and sedimentation are processes that continually reshape Earth’s surface.', 5, 3),
  ('sshs-grade-11-earth-and-space-science-2:standard:performance:period-3:item-1', 'sshs-grade-11-earth-and-space-science-2', 3, null, 'performance', 'By the end of the quarter, learners simulate Earth''s geological processes using concrete and conceptual models. They use practical examples to illustrate and explain Earth processes and their impacts on local, national, regional, and global landforms over time.', 1, 3),
  ('sshs-grade-11-earth-and-space-science-2:standard:content:period-4:item-1', 'sshs-grade-11-earth-and-space-science-2', 4, 'D03', 'content', 'the Earth is a complex system where energy and matter flow across interconnected subsystems, shaping the environment and sustaining life;', 1, 4),
  ('sshs-grade-11-earth-and-space-science-2:standard:content:period-4:item-2', 'sshs-grade-11-earth-and-space-science-2', 4, 'D04', 'content', 'the biogeochemical cycle are processes that regulate Earth''s subsystems;', 2, 4),
  ('sshs-grade-11-earth-and-space-science-2:standard:content:period-4:item-3', 'sshs-grade-11-earth-and-space-science-2', 4, 'D05', 'content', 'water resources are unevenly distributed across the Earth, affecting regional climate, ecosystems, and human activities;', 3, 4),
  ('sshs-grade-11-earth-and-space-science-2:standard:content:period-4:item-4', 'sshs-grade-11-earth-and-space-science-2', 4, 'D05', 'content', 'water in different forms plays a vital role in forming landscapes, supporting ecosystems, and sustaining human needs;', 4, 4),
  ('sshs-grade-11-earth-and-space-science-2:standard:content:period-4:item-5', 'sshs-grade-11-earth-and-space-science-2', 4, 'D05', 'content', 'human activities have a profound impact on water quality and availability;', 5, 4),
  ('sshs-grade-11-earth-and-space-science-2:standard:performance:period-4:item-1', 'sshs-grade-11-earth-and-space-science-2', 4, null, 'performance', 'By the end of the quarter, learners relate the Earth’s interconnected subsystems and describe how these impact sustaining and supporting life and ecological balance within the Philippines and on the planet. Learners describe and explain the implications of these processes for the Philippines. Learners apply scientific models and concepts, data analysis, and scientific reports to describe local and global water systems and their sustainability for the Philippines.', 1, 5),
  ('sshs-grade-11-effective-communication:standard:content:period-1:item-1', 'sshs-grade-11-effective-communication', 1, null, 'content', 'The learners demonstrate effective communication in personal and interpersonal contexts through spoken, written, and multimodal forms; they understand that interaction patterns are adaptive and collaborative, and that trust-building, emotional reciprocity, and contextual understanding foster meaningful relationships.', 1, 3),
  ('sshs-grade-11-effective-communication:standard:performance:period-1:item-1', 'sshs-grade-11-effective-communication', 1, null, 'performance', 'communication events; engage in intrapersonal communication, including goal-setting, reflection and journaling; participate in extended conversations and discussions on a variety of personal and interpersonal topics; provide short and extended responses to questions pertaining to the content and intent of conversations and correspondences; and produce short and extended personal and interpersonal correspondence in formats such as, but not limited to, letters, email, texting and messaging, and social media posts.', 1, 3),
  ('sshs-grade-11-effective-communication:standard:content:period-2:item-1', 'sshs-grade-11-effective-communication', 2, null, 'content', 'The learners demonstrate effective communication in social and cultural contexts through oral, written, and multimodal forms; they understand that interaction patterns reflect social roles, group norms and dynamics, and cultural diversity, and that openness, intercultural sensitivity, inclusive language, and ethical considerations foster respectful engagement with diverse communities in public settings and digital spaces.', 1, 4),
  ('sshs-grade-11-effective-communication:standard:performance:period-2:item-1', 'sshs-grade-11-effective-communication', 2, null, 'performance', 'The learners are able to participate in communicative events that involve diverse social and cultural groups; engage in formal and informal interactions that reflect sensitivity to cultural norms, group roles and dynamics, and social practices; respond appropriately and respectfully in forums and public exchanges on social and cultural issues; and produce spoken, written, and multimodal texts such as public service announcements, opinion pieces, cultural narratives, community blog posts, and reflective commentaries that promote inclusive and ethical social communication.', 1, 4),
  ('sshs-grade-11-effective-communication:standard:content:period-3:item-1', 'sshs-grade-11-effective-communication', 3, null, 'content', 'The learners demonstrate effective communication in academic and training contexts through spoken, written, and multimodal forms; they understand that interaction patterns in academic and training contexts are formal, structured, and discipline-specific, and that intellectual integrity, honest and respectful critique, and inclusive language foster meaningful academic and training engagement.', 1, 6),
  ('sshs-grade-11-effective-communication:standard:performance:period-3:item-1', 'sshs-grade-11-effective-communication', 3, null, 'performance', 'The learners produce spoken, written, and multimodal academic and technical texts for specific purposes and audiences, such as, but not limited to, articles, research reports, public speaking presentations, reviews, and podcasts; prepare note cards and reference lists in support of these texts; convert these texts into presentation format give and use feedback on the content, structure and language of communication to i Use language, tone, and structure appropriately for audience, purpose, and context in discussing a variety of academic and technical topics. Follow procedures, instructions, or processes in spoken, written, or multimodal forms (e.g., figures, diagrams, charts) to successfully achieve outcomes. Participate constructively in academic or technical lectures, presentations, or discussions by formulating and asking questions, providing feedback, and responding appropriately.', 1, 6),
  ('sshs-grade-11-effective-communication:standard:content:period-4:item-1', 'sshs-grade-11-effective-communication', 4, null, 'content', 'The learners demonstrate effective communication in professional and work contexts through oral, written, and multimodal forms; they understand that professional and workplace interaction patterns are goal-oriented, concise, and context-specific, and that clarity, formality, hierarchical awareness, emotional regulation, cultural sensitivity, and ethical responsibility foster effective and professional workplace relationships.', 1, 8),
  ('sshs-grade-11-effective-communication:standard:performance:period-4:item-1', 'sshs-grade-11-effective-communication', 4, null, 'performance', 'The learners compose types of correspondence following specific writing conventions; create professional profiles and resumés fit for purpose and audience; draft business case studies, project proposals, and business reports; propose job ads, corporate publications, or industry articles following brand alignment practices; and participate constructively in interviews, meetings, discussions, and negotiations.', 1, 8),
  ('sshs-grade-11-electrical-installation-maintenance:standard:content:period-1:item-1', 'sshs-grade-11-electrical-installation-maintenance', 1, null, 'content', 'The learners demonstrate an understanding of roughing-in activities for residential/building wiring systems.', 1, 2),
  ('sshs-grade-11-electrical-installation-maintenance:standard:performance:period-1:item-1', 'sshs-grade-11-electrical-installation-maintenance', 1, null, 'performance', 'The learners perform roughing-in activities for residential/building in accordance with PEC standard.', 1, 2),
  ('sshs-grade-11-electrical-installation-maintenance:standard:content:period-2:item-1', 'sshs-grade-11-electrical-installation-maintenance', 2, null, 'content', 'The learners demonstrate an understanding of the installation and termination of wiring fixtures, as well as the use of protective devices in residential/building wiring systems.', 1, 3),
  ('sshs-grade-11-electrical-installation-maintenance:standard:performance:period-2:item-1', 'sshs-grade-11-electrical-installation-maintenance', 2, null, 'performance', 'The learners perform installation and termination of wiring fixtures, as well as the use of protective devices in residential/building wiring systems according to PEC standard.', 1, 3),
  ('sshs-grade-11-electrical-installation-maintenance:standard:content:period-3:item-1', 'sshs-grade-11-electrical-installation-maintenance', 3, null, 'content', 'The learners demonstrate an understanding of the concepts and principles of Fire Detection and Alarm Systems (FDAS).', 1, 4),
  ('sshs-grade-11-electrical-installation-maintenance:standard:content:period-3:item-2', 'sshs-grade-11-electrical-installation-maintenance', 3, null, 'content', 'The learners demonstrate an understanding of the concepts and principles of Closed-Circuit Television (CCTV).', 2, 5),
  ('sshs-grade-11-electrical-installation-maintenance:standard:performance:period-3:item-1', 'sshs-grade-11-electrical-installation-maintenance', 3, null, 'performance', 'The learners perform installation of Fire Detection and Alarm Systems (FDAS) according to PEC standard.', 1, 4),
  ('sshs-grade-11-electrical-installation-maintenance:standard:performance:period-3:item-2', 'sshs-grade-11-electrical-installation-maintenance', 3, null, 'performance', 'The learners perform installation of Closed-Circuit Television (CCTV) according to PEC standard.', 2, 5),
  ('sshs-grade-11-electronics-product-assembly-and-servicing:standard:content:period-1:item-1', 'sshs-grade-11-electronics-product-assembly-and-servicing', 1, null, 'content', 'The learners demonstrate understanding of the principles in electronic systems assembling and servicing, identification of electronic components, PCB designing, soldering and desoldering, and assembly of electronic products.', 1, 2),
  ('sshs-grade-11-electronics-product-assembly-and-servicing:standard:performance:period-1:item-1', 'sshs-grade-11-electronics-product-assembly-and-servicing', 1, null, 'performance', 'The learners perform procedures in assembling and testing of electronic components, and power supply assembly following existing standard.', 1, 2),
  ('sshs-grade-11-electronics-product-assembly-and-servicing:standard:content:period-2:item-1', 'sshs-grade-11-electronics-product-assembly-and-servicing', 2, null, 'content', 'The learners demonstrate an understanding of the principles of appliances with electric motors, appliances with heating components, and electronic controlled lighting units.', 1, 3),
  ('sshs-grade-11-electronics-product-assembly-and-servicing:standard:performance:period-2:item-1', 'sshs-grade-11-electronics-product-assembly-and-servicing', 2, null, 'performance', 'The learners perform servicing of appliances with electric motors, appliances with heating elements, and rechargeable and electronic-controlled lighting units ensuring adherence to safety standards.', 1, 3),
  ('sshs-grade-11-electronics-product-assembly-and-servicing:standard:content:period-3:item-1', 'sshs-grade-11-electronics-product-assembly-and-servicing', 3, null, 'content', 'The learners demonstrate an understanding of the principles of Closed-Circuit Television (CCTV) systems, and fire alarm systems.', 1, 4),
  ('sshs-grade-11-electronics-product-assembly-and-servicing:standard:performance:period-3:item-1', 'sshs-grade-11-electronics-product-assembly-and-servicing', 3, null, 'performance', 'The learners perform servicing of Closed-Circuit Television (CCTV) systems, and fire alarm systems ensuring adherence to safety precautions.', 1, 4),
  ('sshs-grade-11-electronics-product-assembly-and-servicing:standard:content:period-4:item-1', 'sshs-grade-11-electronics-product-assembly-and-servicing', 4, null, 'content', 'The learners demonstrate an understanding of the principles of audio products and systems, television, control boards and motor controllers, sensors and actuators.', 1, 6),
  ('sshs-grade-11-electronics-product-assembly-and-servicing:standard:performance:period-4:item-1', 'sshs-grade-11-electronics-product-assembly-and-servicing', 4, null, 'performance', 'The learners perform procedures in servicing audio products and systems, control boards and motor controllers, and sensors and actuators ensuring adherence to safety precautions.', 1, 6),
  ('sshs-grade-11-entrepreneurship:standard:content:period-1:item-1', 'sshs-grade-11-entrepreneurship', 1, null, 'content', 'The learners demonstrate understanding of the key concepts, principles, and core competencies in entrepreneurship including the planning and resourcing of business enterprises.', 1, 2),
  ('sshs-grade-11-entrepreneurship:standard:performance:period-1:item-1', 'sshs-grade-11-entrepreneurship', 1, null, 'performance', 'Learners develop a proposal for a product or service to present to potential investors.', 1, 2),
  ('sshs-grade-11-entrepreneurship:standard:content:period-2:item-1', 'sshs-grade-11-entrepreneurship', 2, null, 'content', 'The learners demonstrate understanding of the processes of implementation, management, legalization, and performance assessment of a business enterprise.', 1, 3),
  ('sshs-grade-11-entrepreneurship:standard:performance:period-2:item-1', 'sshs-grade-11-entrepreneurship', 2, null, 'performance', 'Learners simulate a business plan in an identified market environment and assess the outcomes of the business performance.', 1, 3),
  ('sshs-grade-11-events-management-services:standard:content:period-1:item-1', 'sshs-grade-11-events-management-services', 1, null, 'content', 'The learners demonstrate an understanding of the fundamental concepts, processes, and roles within the event management industry.', 1, 2),
  ('sshs-grade-11-events-management-services:standard:content:period-1:item-2', 'sshs-grade-11-events-management-services', 1, null, 'content', 'The learner demonstrates an understanding of developing event programs and selecting appropriate venues.', 2, 10),
  ('sshs-grade-11-events-management-services:standard:performance:period-1:item-1', 'sshs-grade-11-events-management-services', 1, null, 'performance', 'The learners conceptualize event plans by preparing event proposals and budgets.', 1, 2),
  ('sshs-grade-11-events-management-services:standard:performance:period-1:item-2', 'sshs-grade-11-events-management-services', 1, null, 'performance', 'The learner applies knowledge on developing event programs and selecting appropriate venues.', 2, 10),
  ('sshs-grade-11-events-management-services:standard:content:period-3:item-1', 'sshs-grade-11-events-management-services', 3, null, 'content', 'The learners demonstrate an understanding of legal regulatory requirements in managing events.', 1, 12),
  ('sshs-grade-11-events-management-services:standard:performance:period-3:item-1', 'sshs-grade-11-events-management-services', 3, null, 'performance', 'The learners prepare legal documents needed in managing events.', 1, 12),
  ('sshs-grade-11-events-management-services:standard:content:period-4:item-1', 'sshs-grade-11-events-management-services', 4, null, 'content', 'The learners demonstrate an understanding of managing events', 1, 15),
  ('sshs-grade-11-events-management-services:standard:performance:period-4:item-1', 'sshs-grade-11-events-management-services', 4, null, 'performance', 'The learners manage an event', 1, 15),
  ('sshs-grade-11-filipino-1-wika-at-komunikasyon-sa-akademikong-filipino:standard:content:period-1:item-1', 'sshs-grade-11-filipino-1-wika-at-komunikasyon-sa-akademikong-filipino', 1, null, 'content', 'Naipamamalas ng mga mag-aaral ang kritikal na pag-unawa sa wika at mga wika sa Pilipinas tungo sa pagpapahalaga sa Filipino bilang wikang pambansa', 1, 2),
  ('sshs-grade-11-filipino-1-wika-at-komunikasyon-sa-akademikong-filipino:standard:performance:period-1:item-1', 'sshs-grade-11-filipino-1-wika-at-komunikasyon-sa-akademikong-filipino', 1, null, 'performance', 'Nakasusulat ng kritikal na sanaysay na tumatalakay sa sitwasyon ng wikang Filipino sa lipunang Pilipino', 1, 2),
  ('sshs-grade-11-filipino-1-wika-at-komunikasyon-sa-akademikong-filipino:standard:content:period-2:item-1', 'sshs-grade-11-filipino-1-wika-at-komunikasyon-sa-akademikong-filipino', 2, null, 'content', 'Naipamamalas ng mga mag-aaral ang kritikal na pag-unawa sa mga batayang kaalaman sa komunikasyon at kakayahan sa akademikong Filipino sa pagsusuri ng mga teksto sa iba’t ibang disiplina tungo sa mabisang pakikipagdiskurso', 1, 4),
  ('sshs-grade-11-filipino-1-wika-at-komunikasyon-sa-akademikong-filipino:standard:performance:period-2:item-1', 'sshs-grade-11-filipino-1-wika-at-komunikasyon-sa-akademikong-filipino', 2, null, 'performance', 'Nakapagsasagawa ng kritikal na talakayan tungkol sa isang napapanahong usaping panlipunan Almario, V., at Komisyon sa Wikang Filipino. Manwal sa Masinop na Pagsulat. Maynila: Komisyon sa Wikang Filipino.', 1, 4),
  ('sshs-grade-11-filipino-2-filipino-para-sa-larang-teknikal-propesyonal:standard:content:period-1:item-1', 'sshs-grade-11-filipino-2-filipino-para-sa-larang-teknikal-propesyonal', 1, null, 'content', 'Naipamamalas ng mga mag-aaral ang kasanayan sa akademikong Filipino sa kritikal na pag-unawa ng at pagsusuri sa mga uri at elemento ng mga tekstong multimodal sa teknikal-propesyonal na larang.', 1, 2),
  ('sshs-grade-11-filipino-2-filipino-para-sa-larang-teknikal-propesyonal:standard:performance:period-1:item-1', 'sshs-grade-11-filipino-2-filipino-para-sa-larang-teknikal-propesyonal', 1, null, 'performance', 'Nakapagsasagawa ng multimodal na presentasyon ng piniling produkto o serbisyo gamit ang akademikong Filipino.', 1, 2),
  ('sshs-grade-11-filipino-2-filipino-para-sa-larang-teknikal-propesyonal:standard:content:period-2:item-1', 'sshs-grade-11-filipino-2-filipino-para-sa-larang-teknikal-propesyonal', 2, null, 'content', 'Naipamamalas ng mga mag-aaral ang kasanayan sa akademikong Filipino sa kritikal na pag-unawa, pagsusuri at pagbuo ng mga teksto sa teknikal-propesyonal na larang', 1, 4),
  ('sshs-grade-11-filipino-2-filipino-para-sa-larang-teknikal-propesyonal:standard:performance:period-2:item-1', 'sshs-grade-11-filipino-2-filipino-para-sa-larang-teknikal-propesyonal', 2, null, 'performance', 'Nakabubuo ng portfolio ng mga tekstong teknikal-propesyonal', 1, 4),
  ('sshs-grade-11-filipino-2-filipino-sa-isports:standard:content:period-1:item-1', 'sshs-grade-11-filipino-2-filipino-sa-isports', 1, null, 'content', 'Naipamamalas ng mga mag-aaral ang kasanayan sa akademikong Filipino sa kritikal na pag-unawa, pagsusuri at pagbuo ng iba’t ibang sulating pang-isports gaya ng ulat ng laro, plano ng laro, patakarang pang-isports, at iba pang tekstong teknikal pang-isports.', 1, 2),
  ('sshs-grade-11-filipino-2-filipino-sa-isports:standard:performance:period-1:item-1', 'sshs-grade-11-filipino-2-filipino-sa-isports', 1, null, 'performance', 'Nakabubuo ng mga sulating pang-isports batay sa elemento at etika sa pagsulat gamit ang akademikong Filipino.', 1, 2),
  ('sshs-grade-11-filipino-2-filipino-sa-isports:standard:content:period-2:item-1', 'sshs-grade-11-filipino-2-filipino-sa-isports', 2, null, 'content', 'Naipamamalas ng mga mag-aaral ang kasanayan sa akademikong Filipino sa kritikal na pag-unawa, pagsusuri at pagsulat ng iba’t ibang anyo ng mga sulating pang-isports gaya ng pangkalakalan, serbisyo, plano sa pangangalaga ng kalusugan, at iba pang sulating panserbisyo at pangkalakalan sa larang pampalakasan.', 1, 4),
  ('sshs-grade-11-filipino-2-filipino-sa-isports:standard:performance:period-2:item-1', 'sshs-grade-11-filipino-2-filipino-sa-isports', 2, null, 'performance', 'Nakabubuo ng sports brochure kaugnay ng mahahalagang datos na nakalap sa pangangalaga ng mental at pisikal na kalusugan ng manlalaro sa napiling isports', 1, 4),
  ('sshs-grade-11-filipino-2-filipino-sa-sining-at-disenyo:standard:content:period-1:item-1', 'sshs-grade-11-filipino-2-filipino-sa-sining-at-disenyo', 1, null, 'content', 'Naipamamalas ng mga mag-aaral ang kasanayan sa paggamit ng komunikatibong Filipino sa kritikal na pag-unawa ng mga batayang kaalaman sa sining at disenyo, partikular na sa pagsusuri at pagpapahalaga sa mga uri ng literatura. Paghahanda ito sa pagsulat ng rebyu ng mga likhang-sining sa komunidad.', 1, 2),
  ('sshs-grade-11-filipino-2-filipino-sa-sining-at-disenyo:standard:performance:period-1:item-1', 'sshs-grade-11-filipino-2-filipino-sa-sining-at-disenyo', 1, null, 'performance', 'Nakasusulat ng rebyu ng isang likhang-sining at disenyo sa komunidad gamit ang komunikatibong Filipino.', 1, 2),
  ('sshs-grade-11-filipino-2-filipino-sa-sining-at-disenyo:standard:content:period-2:item-1', 'sshs-grade-11-filipino-2-filipino-sa-sining-at-disenyo', 2, null, 'content', 'Naipamamalas ng mga mag-aaral ang kasanayan sa paggamit ng komunikatibong Filipino sa kritikal na pag-unawa ng mga batayang kaalaman sa sining at disenyo at sa pagsusuri at pagpapahalaga sa mga uri nito na broadcast media, sining panteatro, sining biswal at arkitektura tungo sa pagsasagawa ng eksibit.', 1, 4),
  ('sshs-grade-11-filipino-2-filipino-sa-sining-at-disenyo:standard:performance:period-2:item-1', 'sshs-grade-11-filipino-2-filipino-sa-sining-at-disenyo', 2, null, 'performance', 'Nakapagsasagawa ng eksibit ng mga anyong sining na ginagamitan ng mabisang komunikatibong Filipino.', 1, 4),
  ('sshs-grade-11-filipino-identity-through-the-arts:standard:content:period-1:item-1', 'sshs-grade-11-filipino-identity-through-the-arts', 1, null, 'content', 'Learners demonstrate an understanding of Philippine indigenous and traditional arts as repositories of memory and collective human experience, as constructions of Filipino identity, and as wellsprings for continuity and innovation in the performing arts.', 1, 2),
  ('sshs-grade-11-filipino-identity-through-the-arts:standard:performance:period-1:item-1', 'sshs-grade-11-filipino-identity-through-the-arts', 1, null, 'performance', 'Learners create performances that integrate significant aspects of indigenous and traditional expressions as markers of Filipino identity and heritage.', 1, 2),
  ('sshs-grade-11-filipino-identity-through-the-arts:standard:content:period-2:item-1', 'sshs-grade-11-filipino-identity-through-the-arts', 2, null, 'content', 'The learners demonstrate an understanding of Philippine indigenous and traditional arts as repositories of memory and collective human experience, as constructions of Filipino identity, and as wellsprings for continuity and innovation in visual arts, literary arts, and architecture', 1, 3),
  ('sshs-grade-11-filipino-identity-through-the-arts:standard:performance:period-2:item-1', 'sshs-grade-11-filipino-identity-through-the-arts', 2, null, 'performance', 'The learners create artistic works that integrate local materials and significant aspects of indigenous and traditional arts as markers of Filipino identity and heritage.', 1, 3),
  ('sshs-grade-11-finite-mathematics-1:standard:content:period-1:item-1', 'sshs-grade-11-finite-mathematics-1', 1, 'D01', 'content', 'Symmetries in nature and art', 1, 3),
  ('sshs-grade-11-finite-mathematics-1:standard:content:period-1:item-2', 'sshs-grade-11-finite-mathematics-1', 1, 'D01', 'content', 'Different linear transformations (geometric approach)', 2, 3),
  ('sshs-grade-11-finite-mathematics-1:standard:content:period-1:item-3', 'sshs-grade-11-finite-mathematics-1', 1, 'D01', 'content', 'Tiling and Tessellations', 3, 3),
  ('sshs-grade-11-finite-mathematics-1:standard:content:period-1:item-4', 'sshs-grade-11-finite-mathematics-1', 1, 'D01', 'content', 'Frieze Patterns', 4, 3),
  ('sshs-grade-11-finite-mathematics-1:standard:content:period-1:item-5', 'sshs-grade-11-finite-mathematics-1', 1, 'D02', 'content', 'the Golden Ratio in nature and art', 5, 3),
  ('sshs-grade-11-finite-mathematics-1:standard:content:period-1:item-6', 'sshs-grade-11-finite-mathematics-1', 1, 'D02', 'content', 'Fibonacci Sequence in nature and art', 6, 3),
  ('sshs-grade-11-finite-mathematics-1:standard:content:period-1:item-7', 'sshs-grade-11-finite-mathematics-1', 1, 'D02', 'content', 'Fractals', 7, 3),
  ('sshs-grade-11-finite-mathematics-1:standard:performance:period-1:item-1', 'sshs-grade-11-finite-mathematics-1', 1, null, 'performance', 'By the end of the quarter, the learners are able to contribute to a class exhibit of artworks inspired by geometric symmetries, tessellations, Frieze patterns, the golden ratio, the Fibonacci sequence, or fractals. Each artwork should be accompanied by a description detailing the mathematics involved.', 1, 3),
  ('sshs-grade-11-finite-mathematics-1:standard:content:period-2:item-1', 'sshs-grade-11-finite-mathematics-1', 2, 'D03', 'content', 'Fundamental concepts of matrices and basic operations', 1, 4),
  ('sshs-grade-11-finite-mathematics-1:standard:content:period-2:item-2', 'sshs-grade-11-finite-mathematics-1', 2, 'D03', 'content', 'Elementary row operations', 2, 4),
  ('sshs-grade-11-finite-mathematics-1:standard:content:period-2:item-3', 'sshs-grade-11-finite-mathematics-1', 2, 'D03', 'content', 'Determinants and their properties', 3, 4),
  ('sshs-grade-11-finite-mathematics-1:standard:content:period-2:item-4', 'sshs-grade-11-finite-mathematics-1', 2, 'D04', 'content', 'Fundamental concepts of linear programming', 4, 4),
  ('sshs-grade-11-finite-mathematics-1:standard:content:period-2:item-5', 'sshs-grade-11-finite-mathematics-1', 2, 'D04', 'content', 'Graphical method', 5, 4),
  ('sshs-grade-11-finite-mathematics-1:standard:content:period-2:item-6', 'sshs-grade-11-finite-mathematics-1', 2, 'D04', 'content', 'Simplex Method', 6, 4),
  ('sshs-grade-11-finite-mathematics-1:standard:performance:period-2:item-1', 'sshs-grade-11-finite-mathematics-1', 2, null, 'performance', 'By the end of the quarter, the learners are able to model real-world situations using matrices and matrix operations. They are also able to formulate linear programming models and solve them using either the graphical or simplex method.', 1, 5),
  ('sshs-grade-11-finite-mathematics-2:standard:content:period-1:item-1', 'sshs-grade-11-finite-mathematics-2', 1, null, 'content', 'The learners demonstrate', 1, 3),
  ('sshs-grade-11-finite-mathematics-2:standard:content:period-1:item-2', 'sshs-grade-11-finite-mathematics-2', 1, 'D01', 'content', 'Fundamental Principles of Counting', 2, 3),
  ('sshs-grade-11-finite-mathematics-2:standard:content:period-1:item-3', 'sshs-grade-11-finite-mathematics-2', 1, 'D01', 'content', 'Combination and permutation', 3, 3),
  ('sshs-grade-11-finite-mathematics-2:standard:content:period-1:item-4', 'sshs-grade-11-finite-mathematics-2', 1, 'D01', 'content', 'Variations in Counting', 4, 3),
  ('sshs-grade-11-finite-mathematics-2:standard:content:period-1:item-5', 'sshs-grade-11-finite-mathematics-2', 1, 'D02', 'content', 'Probability of an event', 5, 3),
  ('sshs-grade-11-finite-mathematics-2:standard:content:period-1:item-6', 'sshs-grade-11-finite-mathematics-2', 1, 'D02', 'content', 'Addition of probabilities', 6, 3),
  ('sshs-grade-11-finite-mathematics-2:standard:content:period-1:item-7', 'sshs-grade-11-finite-mathematics-2', 1, 'D02', 'content', 'Conditional probability and independent events', 7, 3),
  ('sshs-grade-11-finite-mathematics-2:standard:performance:period-1:item-1', 'sshs-grade-11-finite-mathematics-2', 1, null, 'performance', 'By the end of the quarter, the learners are able to apply combinations and permutations in counting the number of ways to select and arrange objects. In addition, they are able to solve problems involving probabilities.', 1, 3),
  ('sshs-grade-11-finite-mathematics-2:standard:content:period-2:item-1', 'sshs-grade-11-finite-mathematics-2', 2, null, 'content', 'The learners demonstrate', 1, 4),
  ('sshs-grade-11-finite-mathematics-2:standard:content:period-2:item-2', 'sshs-grade-11-finite-mathematics-2', 2, 'D03', 'content', 'Divisibility', 2, 4),
  ('sshs-grade-11-finite-mathematics-2:standard:content:period-2:item-3', 'sshs-grade-11-finite-mathematics-2', 2, 'D03', 'content', 'Greatest common divisor and least common multiple', 3, 4),
  ('sshs-grade-11-finite-mathematics-2:standard:content:period-2:item-4', 'sshs-grade-11-finite-mathematics-2', 2, 'D03', 'content', 'Modular Arithmetic', 4, 4),
  ('sshs-grade-11-finite-mathematics-2:standard:content:period-2:item-5', 'sshs-grade-11-finite-mathematics-2', 2, 'D04', 'content', 'Fundamental concepts of graph theory', 5, 4),
  ('sshs-grade-11-finite-mathematics-2:standard:content:period-2:item-6', 'sshs-grade-11-finite-mathematics-2', 2, 'D04', 'content', 'Graph connectivity and transversability', 6, 4),
  ('sshs-grade-11-finite-mathematics-2:standard:content:period-2:item-7', 'sshs-grade-11-finite-mathematics-2', 2, 'D04', 'content', 'Spanning Trees and Shortest Paths', 7, 4),
  ('sshs-grade-11-finite-mathematics-2:standard:performance:period-2:item-1', 'sshs-grade-11-finite-mathematics-2', 2, null, 'performance', 'By the end of the quarter, the learners are able to perform number-theoretic operations (GCD, LCM, modular arithmetic) and solve problems involving applications of modular arithmetic and linear Diophantine equations. In addition, they are able to solve problems involving graph theory algorithms (Eulerian and Hamiltonian paths and circuits, spanning trees, shortest paths), and discuss the applications of graphs in transportation, communication, network design, productivity, etc., through a presentation or written work.', 1, 4),
  ('sshs-grade-11-fish-capture:standard:content:period-1:item-1', 'sshs-grade-11-fish-capture', 1, null, 'content', 'The learners demonstrate an understanding of the overview of fish capture, legal bases in protecting the marine environment, tools, materials, and equipment in fish capture operations and safe navigation information.', 1, 2),
  ('sshs-grade-11-fish-capture:standard:performance:period-1:item-1', 'sshs-grade-11-fish-capture', 1, null, 'performance', 'The learners perform safe navigation applying the weather information in a simulated environment.', 1, 2),
  ('sshs-grade-11-fish-capture:standard:content:period-2:item-1', 'sshs-grade-11-fish-capture', 2, null, 'content', 'The learners demonstrate an understanding of types, functions, and maintenance of fishing gears and fish capture operations.', 1, 4),
  ('sshs-grade-11-fish-capture:standard:performance:period-2:item-1', 'sshs-grade-11-fish-capture', 2, null, 'performance', 'The learners perform maintenance of fishing gears and fish capture operations.', 1, 4),
  ('sshs-grade-11-fish-capture:standard:content:period-3:item-1', 'sshs-grade-11-fish-capture', 3, null, 'content', 'The learners demonstrate an understanding of the condition, seaworthiness, operation and navigation of a municipal vessel.', 1, 5),
  ('sshs-grade-11-fish-capture:standard:performance:period-3:item-1', 'sshs-grade-11-fish-capture', 3, null, 'performance', 'The learner performs municipal vessel operation and navigation.', 1, 5),
  ('sshs-grade-11-fish-capture:standard:content:period-4:item-1', 'sshs-grade-11-fish-capture', 4, null, 'content', 'The learners demonstrate an understanding of handling, storing, transporting, and recording of aquatic products.', 1, 6),
  ('sshs-grade-11-fish-capture:standard:performance:period-4:item-1', 'sshs-grade-11-fish-capture', 4, null, 'performance', 'The learners perform handling, storing, transporting, and recording of aquatic products adhering to food safety standards.', 1, 6),
  ('sshs-grade-11-food-and-beverage-operation:standard:content:period-1:item-1', 'sshs-grade-11-food-and-beverage-operation', 1, null, 'content', 'The learners demonstrate an understanding of the principles of providing food and beverage operations.', 1, 2),
  ('sshs-grade-11-food-and-beverage-operation:standard:performance:period-1:item-1', 'sshs-grade-11-food-and-beverage-operation', 1, null, 'performance', 'Learners demonstrate comprehensive skills in providing food and beverage services operations.', 1, 2),
  ('sshs-grade-11-food-and-beverage-operation:standard:content:period-2:item-1', 'sshs-grade-11-food-and-beverage-operation', 2, null, 'content', 'The learners demonstrate an understanding of the principles of providing food and beverage operations related to alcoholic and non-alcoholic beverages, beverage service, restaurant service, and in-room dining service', 1, 5),
  ('sshs-grade-11-food-and-beverage-operation:standard:performance:period-2:item-1', 'sshs-grade-11-food-and-beverage-operation', 2, null, 'performance', 'Learners demonstrate skills in providing food and beverage services.', 1, 5),
  ('sshs-grade-11-food-and-beverage-operation:standard:content:period-3:item-1', 'sshs-grade-11-food-and-beverage-operation', 3, null, 'content', 'The learners demonstrate an understanding of the preparing coffee beverages', 1, 6),
  ('sshs-grade-11-food-and-beverage-operation:standard:performance:period-3:item-1', 'sshs-grade-11-food-and-beverage-operation', 3, null, 'performance', 'The learners perform procedures in preparing coffee based and non-coffee-based beverages based on the industry practices', 1, 6),
  ('sshs-grade-11-food-and-beverage-operation:standard:content:period-4:item-1', 'sshs-grade-11-food-and-beverage-operation', 4, null, 'content', 'The learners demonstrate the skills of preparing a variety of coffee-based beverages.', 1, 8),
  ('sshs-grade-11-food-and-beverage-operation:standard:content:period-4:item-2', 'sshs-grade-11-food-and-beverage-operation', 4, null, 'content', 'The learners demonstrate understanding in preparing non-coffee beverages.', 2, 9),
  ('sshs-grade-11-food-and-beverage-operation:standard:content:period-4:item-3', 'sshs-grade-11-food-and-beverage-operation', 4, null, 'content', 'The learners demonstrate an understanding of basic steps in cashiering, general control procedures and beverage costing.', 3, 10),
  ('sshs-grade-11-food-and-beverage-operation:standard:performance:period-4:item-1', 'sshs-grade-11-food-and-beverage-operation', 4, null, 'performance', 'The learners demonstrate skills in preparing and presenting varieties of coffee beverages.', 1, 8),
  ('sshs-grade-11-food-and-beverage-operation:standard:performance:period-4:item-2', 'sshs-grade-11-food-and-beverage-operation', 4, null, 'performance', 'The learners perform skills in preparing and presenting non-coffee beverages.', 2, 9),
  ('sshs-grade-11-food-and-beverage-operation:standard:performance:period-4:item-3', 'sshs-grade-11-food-and-beverage-operation', 4, null, 'performance', 'The learners perform basic cashiering, general control procedures and beverage costing.', 3, 10),
  ('sshs-grade-11-food-processing:standard:content:period-1:item-1', 'sshs-grade-11-food-processing', 1, null, 'content', 'The learners demonstrate an understanding of the overview, use, and maintenance of tools and equipment, and Occupational Safety and Health (OSH) practices in food processing and fish product packaging.', 1, 2),
  ('sshs-grade-11-food-processing:standard:performance:period-1:item-1', 'sshs-grade-11-food-processing', 1, null, 'performance', 'The learners perform maintenance of food processing and fish product packaging tools, materials, and equipment in accordance with industry standards.', 1, 2),
  ('sshs-grade-11-food-processing:standard:content:period-2:item-1', 'sshs-grade-11-food-processing', 2, null, 'content', 'The learners demonstrate an understanding of the principles in processing food through sugar concentration, packaging, labeling, and costing of food products.', 1, 4),
  ('sshs-grade-11-food-processing:standard:performance:period-2:item-1', 'sshs-grade-11-food-processing', 2, null, 'performance', 'The learners perform food processing through sugar concentration, packaging, labeling, and costing of food products in accordance with industry standards.', 1, 4),
  ('sshs-grade-11-food-processing:standard:content:period-3:item-1', 'sshs-grade-11-food-processing', 3, null, 'content', 'The learners demonstrate an understanding of the principles in processing food through salting, curing, and smoking, as well as fermentation and pickling, and packaging, labeling, and costing of food products.', 1, 7),
  ('sshs-grade-11-food-processing:standard:performance:period-3:item-1', 'sshs-grade-11-food-processing', 3, null, 'performance', 'The learners perform food processing through salting, curing, and smoking; fermentation and pickling, packaging, labeling, and costing of food products in accordance with industry standards.', 1, 7),
  ('sshs-grade-11-food-processing:standard:content:period-4:item-1', 'sshs-grade-11-food-processing', 4, null, 'content', 'The learners demonstrate an understanding of the principles processing food through drying and dehydration and thermal application, as well as packaging, labeling, costing of food products, and marketing processed foods.', 1, 8),
  ('sshs-grade-11-food-processing:standard:performance:period-4:item-1', 'sshs-grade-11-food-processing', 4, null, 'performance', 'The learners perform food processing through drying and dehydration, and thermal application, costing of food products, packaging, labeling, and marketing of processed foods.', 1, 8),
  ('sshs-grade-11-garments-artisanry:standard:content:period-1:item-1', 'sshs-grade-11-garments-artisanry', 1, null, 'content', 'The learners demonstrate essential knowledge and skills in designing, sewing and assembling upper garments.', 1, 2),
  ('sshs-grade-11-garments-artisanry:standard:performance:period-1:item-1', 'sshs-grade-11-garments-artisanry', 1, null, 'performance', 'The learners create sustainable upper garments following occupational health and safety precautions.', 1, 2),
  ('sshs-grade-11-garments-artisanry:standard:content:period-2:item-1', 'sshs-grade-11-garments-artisanry', 2, null, 'content', 'The learners demonstrate essential knowledge and skills in designing, sewing, and assembling lower garments.', 1, 7),
  ('sshs-grade-11-garments-artisanry:standard:performance:period-2:item-1', 'sshs-grade-11-garments-artisanry', 2, null, 'performance', 'The learners create sustainable lower garments following Occupational Health and Safety precautions.', 1, 8),
  ('sshs-grade-11-garments-artisanry:standard:content:period-3:item-1', 'sshs-grade-11-garments-artisanry', 3, null, 'content', 'The learners demonstrate essential knowledge and skills in designing, sewing, and assembling blazers and trousers.', 1, 9),
  ('sshs-grade-11-garments-artisanry:standard:performance:period-3:item-1', 'sshs-grade-11-garments-artisanry', 3, null, 'performance', 'The learners create blazers and trousers following Occupational Health and Safety precautions.', 1, 9),
  ('sshs-grade-11-garments-artisanry:standard:content:period-4:item-1', 'sshs-grade-11-garments-artisanry', 4, null, 'content', 'The learners demonstrate essential knowledge and skills in designing, sewing, and assembling sleeping garments.', 1, 12),
  ('sshs-grade-11-garments-artisanry:standard:performance:period-4:item-1', 'sshs-grade-11-garments-artisanry', 4, null, 'performance', 'The learners create sustainable sleeping garments and children’s wear following Occupational Health and Safety precautions.', 1, 12),
  ('sshs-grade-11-general-mathematics:standard:content:period-1:item-1', 'sshs-grade-11-general-mathematics', 1, 'D01', 'content', 'business and finance through problems involving earning money, buying, and selling', 1, 2),
  ('sshs-grade-11-general-mathematics:standard:content:period-1:item-2', 'sshs-grade-11-general-mathematics', 1, 'D01', 'content', 'patterns, arithmetic and geometric sequences, and series', 2, 3),
  ('sshs-grade-11-general-mathematics:standard:content:period-1:item-3', 'sshs-grade-11-general-mathematics', 1, 'D01', 'content', 'financial application of sequence and series', 3, 3),
  ('sshs-grade-11-general-mathematics:standard:performance:period-1:item-1', 'sshs-grade-11-general-mathematics', 1, null, 'performance', 'By the end of the quarter, the learners are able to conduct a case study on payrolls to compute salaries, wages, deductions, and income for different employee profiles. Learners describe and present how they use sequences and series to make informed decisions on real-life situations involving earning money, buying and selling, acquiring loans, making investments, and planning purchases.', 1, 3),
  ('sshs-grade-11-general-mathematics:standard:content:period-2:item-1', 'sshs-grade-11-general-mathematics', 2, 'D02', 'content', 'measurement and conversion', 1, 4),
  ('sshs-grade-11-general-mathematics:standard:content:period-2:item-2', 'sshs-grade-11-general-mathematics', 2, 'D01', 'content', 'functions and its graphs', 2, 4),
  ('sshs-grade-11-general-mathematics:standard:content:period-2:item-3', 'sshs-grade-11-general-mathematics', 2, 'D01', 'content', 'piecewise functions', 3, 4),
  ('sshs-grade-11-general-mathematics:standard:content:period-2:item-4', 'sshs-grade-11-general-mathematics', 2, 'D03', 'content', 'statistical variables', 4, 5),
  ('sshs-grade-11-general-mathematics:standard:performance:period-2:item-1', 'sshs-grade-11-general-mathematics', 2, null, 'performance', 'By the end of the quarter, the learners are able to present solutions to real-life problems that require measurements and conversions (such as designing a garden, cooking recipes, or building a model) and function models. Learners interpret and explain how they make informed decisions based on the measures of central tendency and variability from data collected for a specific purpose (e.g., report presentations on the analysis of family spending trends using monthly household expenses data).', 1, 5),
  ('sshs-grade-11-general-mathematics:standard:content:period-3:item-1', 'sshs-grade-11-general-mathematics', 3, 'D02', 'content', 'basic trigonometry', 1, 5),
  ('sshs-grade-11-general-mathematics:standard:content:period-3:item-2', 'sshs-grade-11-general-mathematics', 3, 'D02', 'content', 'practical applications of measurements and transformational geometry', 2, 5),
  ('sshs-grade-11-general-mathematics:standard:content:period-3:item-3', 'sshs-grade-11-general-mathematics', 3, 'D03', 'content', 'random variables and sampling', 3, 6),
  ('sshs-grade-11-general-mathematics:standard:performance:period-3:item-1', 'sshs-grade-11-general-mathematics', 3, null, 'performance', 'By the end of the quarter, the learners are able to apply trigonometry and geometric concepts to estimate measurements and construct three-dimensional objects, understanding their shapes and volumes for practical uses like product packaging, furniture, and construction. Learners propose a statistical investigation identifying and justifying the sample size and sampling techniques, and draw conclusions from given data using normal distribution and expected values.', 1, 6),
  ('sshs-grade-11-general-mathematics:standard:content:period-4:item-1', 'sshs-grade-11-general-mathematics', 4, 'D01', 'content', 'compound interest, simple and general annuities, and business and consumer loans', 1, 7),
  ('sshs-grade-11-general-mathematics:standard:content:period-4:item-2', 'sshs-grade-11-general-mathematics', 4, 'D03', 'content', 'basic concepts of a. statistical hypothesis testing b. parametric test of difference c. test of relationships d. simple linear regression', 2, 7),
  ('sshs-grade-11-general-mathematics:standard:content:period-4:item-3', 'sshs-grade-11-general-mathematics', 4, 'D01', 'content', 'logical propositions, syllogisms, and fallacies', 3, 8),
  ('sshs-grade-11-general-mathematics:standard:performance:period-4:item-1', 'sshs-grade-11-general-mathematics', 4, null, 'performance', 'By the end of the quarter, the learners are able to create a financial proposal using comparisons of different investment plans (e.g., time deposits, mutual funds, pension plans) to recommend and explain the best financial strategy. Learners make inferences and explain their reasoning for real-life problems in different disciplines (e.g., market trends, election results, sports statistics) given specific tests of difference and association. Learners evaluate arguments using logic in real-world contexts (e.g., critically analyzing misleading arguments or statements in advertisements, politics, or social media).', 1, 8),
  ('sshs-grade-11-general-science:standard:content:period-1:item-1', 'sshs-grade-11-general-science', 1, 'D01', 'content', 'physics principles apply to numerous aspects of everyday living;', 1, 2),
  ('sshs-grade-11-general-science:standard:content:period-1:item-2', 'sshs-grade-11-general-science', 1, 'D02', 'content', 'understanding linear and angular quantities to describe motion helps in the design of efficient machines;', 2, 2),
  ('sshs-grade-11-general-science:standard:content:period-1:item-3', 'sshs-grade-11-general-science', 1, null, 'content', 'the efficiency of simple and compound machines can be improved by applying basic physics principles;', 3, 3),
  ('sshs-grade-11-general-science:standard:content:period-1:item-4', 'sshs-grade-11-general-science', 1, null, 'content', 'hydraulic systems exploit the relationship between pressure, force, and area to multiply forces and perform tasks;', 4, 3),
  ('sshs-grade-11-general-science:standard:content:period-1:item-5', 'sshs-grade-11-general-science', 1, null, 'content', 'analysis of electricity generation, consumption patterns, and energy-efficiency practices can lead to better energy supply and management; and', 5, 3),
  ('sshs-grade-11-general-science:standard:content:period-1:item-6', 'sshs-grade-11-general-science', 1, null, 'content', 'an understanding of the properties of light and sound leads to their safe and productive application.', 6, 3),
  ('sshs-grade-11-general-science:standard:performance:period-1:item-1', 'sshs-grade-11-general-science', 1, null, 'performance', 'By the end of the quarter, learners identify general physics principles and their applications in daily life. They use scientific principles to solve problems, make informed decisions, and illustrate the applications of physics for self, society, and the environment. They design simple and compound machines and hydraulic systems to demonstrate applications of force, torque, center of mass, and hydraulic-related principles. They evaluate energy-efficient practices in electricity supply and consumption at home and local businesses and explore the advantages and drawbacks of light and sound in medical imaging, security, communication, and entertainment.', 1, 3),
  ('sshs-grade-11-general-science:standard:content:period-2:item-1', 'sshs-grade-11-general-science', 2, 'D03', 'content', 'past research in the field of chemistry provides the foundations for the development of helpful products and processes;', 1, 4),
  ('sshs-grade-11-general-science:standard:content:period-2:item-2', 'sshs-grade-11-general-science', 2, 'D04', 'content', 'household and personal care products contain chemical substances that determine their properties and guide their proper use and disposal;', 2, 4),
  ('sshs-grade-11-general-science:standard:content:period-2:item-3', 'sshs-grade-11-general-science', 2, null, 'content', 'chemical reactions are part of human activities and present in the environment; and', 3, 5),
  ('sshs-grade-11-general-science:standard:content:period-2:item-4', 'sshs-grade-11-general-science', 2, null, 'content', 'chemicals should be handled safely, and solutions can have beneficial and harmful environmental effects.', 4, 5),
  ('sshs-grade-11-general-science:standard:performance:period-2:item-1', 'sshs-grade-11-general-science', 2, null, 'performance', 'By the end of the quarter, learners apply research skills to discover how scientists have impacted our lives. They recognize the significant role of different agencies in the Philippines, such as DOST and DTI, in scientific innovation and development. They show critical thinking in explaining the different substances in household and personal care products, including their benefits and potential risks of using and disposing of them. They demonstrate appropriate and safe handling and use of chemicals. They explain that chemical reactions occur in human activities and the environment, and that several chemical solutions pose a threat to the community.', 1, 5),
  ('sshs-grade-11-general-science:standard:content:period-3:item-1', 'sshs-grade-11-general-science', 3, 'D05', 'content', 'all levels of life have systems of related parts;', 1, 6),
  ('sshs-grade-11-general-science:standard:content:period-3:item-2', 'sshs-grade-11-general-science', 3, 'D05', 'content', 'structures and functions are related at all levels of the organization of life;', 2, 6),
  ('sshs-grade-11-general-science:standard:content:period-3:item-3', 'sshs-grade-11-general-science', 3, 'D06', 'content', 'cells carry out functions that enable organisms to survive;', 3, 6),
  ('sshs-grade-11-general-science:standard:content:period-3:item-4', 'sshs-grade-11-general-science', 3, 'D07', 'content', 'organ systems work together to carry out essential functions of an organism;', 4, 6),
  ('sshs-grade-11-general-science:standard:content:period-3:item-5', 'sshs-grade-11-general-science', 3, 'D08', 'content', 'climate change affects ecosystems and the organisms living in them; and', 5, 6),
  ('sshs-grade-11-general-science:standard:content:period-3:item-6', 'sshs-grade-11-general-science', 3, 'D08', 'content', 'ecosystems are finite and have limited resources.', 6, 6),
  ('sshs-grade-11-general-science:standard:performance:period-3:item-1', 'sshs-grade-11-general-science', 3, null, 'performance', 'By the end of the quarter, learners use examples to describe the relationships among living systems and their components and how the structure of a part relates to its function. They explain the role of cells in perpetuating life and how organ systems work together to maintain optimal health. They conduct investigations on the effects of climate change on local ecosystems.', 1, 7),
  ('sshs-grade-11-general-science:standard:content:period-4:item-1', 'sshs-grade-11-general-science', 4, 'D09', 'content', 'planet Earth is currently the only planet in the Solar System that can support life;', 1, 7),
  ('sshs-grade-11-general-science:standard:content:period-4:item-2', 'sshs-grade-11-general-science', 4, 'D09', 'content', 'an appropriate amount of greenhouse gases helps regulate Earth''s temperature, making it suitable for life;', 2, 7),
  ('sshs-grade-11-general-science:standard:content:period-4:item-3', 'sshs-grade-11-general-science', 4, 'D10', 'content', 'the Philippines is a unique country in terms of its landforms, bodies of water, climate, and biodiversity;', 3, 7),
  ('sshs-grade-11-general-science:standard:content:period-4:item-4', 'sshs-grade-11-general-science', 4, 'D11', 'content', 'earth materials are commonly used in human activity and industry;', 4, 7),
  ('sshs-grade-11-general-science:standard:content:period-4:item-5', 'sshs-grade-11-general-science', 4, null, 'content', 'the Philippines is continuously shaped and reshaped by geologic and hydrometeorological processes;', 5, 8),
  ('sshs-grade-11-general-science:standard:content:period-4:item-6', 'sshs-grade-11-general-science', 4, null, 'content', 'human activities have contributed to the modification of landforms and bodies of water; and', 6, 8),
  ('sshs-grade-11-general-science:standard:content:period-4:item-7', 'sshs-grade-11-general-science', 4, null, 'content', 'impacts of natural hazards need prevention and mitigation strategies and adaptive measures to reduce risks and strengthen resilience.', 7, 8),
  ('sshs-grade-11-general-science:standard:performance:period-4:item-1', 'sshs-grade-11-general-science', 4, null, 'performance', 'By the end of the quarter, learners use evidence from secondary sources to explain the uniqueness of planet Earth compared to other planets in the Solar System. They use models to describe and illustrate the distinctiveness of the Philippine Archipelago, showing how islands are formed through geological processes. They investigate the properties of rocks, minerals, and soil and apply their findings to using earth materials in the Philippines. They integrate ideas, experiences, understanding, and skills to explain geological and hydrometeorological hazards affecting the Philippines. They propose sound, viable, and sustainable mechanisms for hazard mitigation and adaptation.', 1, 8),
  ('sshs-grade-11-hairdressing:standard:content:period-1:item-1', 'sshs-grade-11-hairdressing', 1, null, 'content', 'The learner demonstrates an understanding of the concepts and principles of haircutting.', 1, 2),
  ('sshs-grade-11-hairdressing:standard:performance:period-1:item-1', 'sshs-grade-11-hairdressing', 1, null, 'performance', 'The learners perform haircutting techniques.', 1, 2),
  ('sshs-grade-11-hairdressing:standard:content:period-2:item-1', 'sshs-grade-11-hairdressing', 2, null, 'content', 'The learner demonstrates an understanding of the principles of hair treatments.', 1, 5),
  ('sshs-grade-11-hairdressing:standard:performance:period-2:item-1', 'sshs-grade-11-hairdressing', 2, null, 'performance', 'The learners perform hair treatment following the quality standards of hairdressing.', 1, 5),
  ('sshs-grade-11-hairdressing:standard:content:period-3:item-1', 'sshs-grade-11-hairdressing', 3, null, 'content', 'The learner demonstrates an understanding of the principles of hair bleaching and coloring.', 1, 6),
  ('sshs-grade-11-hairdressing:standard:performance:period-3:item-1', 'sshs-grade-11-hairdressing', 3, null, 'performance', 'The learners perform bleaching and coloring services following the quality standards.', 1, 6),
  ('sshs-grade-11-hairdressing:standard:content:period-4:item-1', 'sshs-grade-11-hairdressing', 4, null, 'content', 'The learner demonstrates an understanding of the principles of hair rebonding and perming.', 1, 8),
  ('sshs-grade-11-hairdressing:standard:performance:period-4:item-1', 'sshs-grade-11-hairdressing', 4, null, 'performance', 'The learners perform rebonding and perming services and safety considerations and industry standards.', 1, 8),
  ('sshs-grade-11-handicrafts-weaving:standard:content:period-1:item-1', 'sshs-grade-11-handicrafts-weaving', 1, null, 'content', 'The learners exhibit knowledge in basketry.', 1, 2),
  ('sshs-grade-11-handicrafts-weaving:standard:performance:period-1:item-1', 'sshs-grade-11-handicrafts-weaving', 1, null, 'performance', 'The learners craft basketry products.', 1, 2),
  ('sshs-grade-11-handicrafts-weaving:standard:content:period-2:item-1', 'sshs-grade-11-handicrafts-weaving', 2, null, 'content', 'The learners demonstrate understanding of the techniques, pattern, and steps in mat weaving.', 1, 3),
  ('sshs-grade-11-handicrafts-weaving:standard:performance:period-2:item-1', 'sshs-grade-11-handicrafts-weaving', 2, null, 'performance', 'The learners apply the techniques in weaving in creating innovative mat products.', 1, 3),
  ('sshs-grade-11-handicrafts-weaving:standard:content:period-3:item-1', 'sshs-grade-11-handicrafts-weaving', 3, null, 'content', 'The learners demonstrate understanding the procedures of handloom weaving in making handloom device.', 1, 5),
  ('sshs-grade-11-handicrafts-weaving:standard:performance:period-3:item-1', 'sshs-grade-11-handicrafts-weaving', 3, null, 'performance', 'The learners apply the procedures in making handloom device for textile weaving.', 1, 5),
  ('sshs-grade-11-handicrafts-weaving:standard:content:period-4:item-1', 'sshs-grade-11-handicrafts-weaving', 4, null, 'content', 'The learners demonstrate an understanding on handloom weaving procedure.', 1, 7),
  ('sshs-grade-11-handicrafts-weaving:standard:performance:period-4:item-1', 'sshs-grade-11-handicrafts-weaving', 4, null, 'performance', 'The learners apply the steps in handloom weaving to create sustainable woven textile products.', 1, 7),
  ('sshs-grade-11-hotel-operation-front-office-services:standard:content:period-1:item-1', 'sshs-grade-11-hotel-operation-front-office-services', 1, null, 'content', 'The learner demonstrates an understanding of hotel front office and its organization and the importance of occupational safety and health standards in hotel operations.', 1, 2),
  ('sshs-grade-11-hotel-operation-front-office-services:standard:performance:period-1:item-1', 'sshs-grade-11-hotel-operation-front-office-services', 1, null, 'performance', 'The learner will create an organizational chart for the front office department, detailing the roles and responsibilities of front office personnel.', 1, 2),
  ('sshs-grade-11-hotel-operation-front-office-services:standard:content:period-2:item-1', 'sshs-grade-11-hotel-operation-front-office-services', 2, null, 'content', 'The learners demonstrate understanding on guestrooms, hotel guest cycle, and reservations.', 1, 4),
  ('sshs-grade-11-hotel-operation-front-office-services:standard:performance:period-2:item-1', 'sshs-grade-11-hotel-operation-front-office-services', 2, null, 'performance', 'The learners perform stages of guest cycle.', 1, 4),
  ('sshs-grade-11-hotel-operation-front-office-services:standard:content:period-3:item-1', 'sshs-grade-11-hotel-operation-front-office-services', 3, null, 'content', 'The learners demonstrate understanding on guest accounting and cashiering, night audit and yield management.', 1, 5),
  ('sshs-grade-11-hotel-operation-front-office-services:standard:performance:period-3:item-1', 'sshs-grade-11-hotel-operation-front-office-services', 3, null, 'performance', 'The learners demonstrate billing procedures, cashiering functions, payment processing methods.', 1, 5),
  ('sshs-grade-11-hotel-operation-front-office-services:standard:content:period-4:item-1', 'sshs-grade-11-hotel-operation-front-office-services', 4, null, 'content', 'The learners demonstrate understanding of PBX (Private Branch Exchange), uniformed services, service excellence, and guest recovery.', 1, 6),
  ('sshs-grade-11-hotel-operation-front-office-services:standard:performance:period-4:item-1', 'sshs-grade-11-hotel-operation-front-office-services', 4, null, 'performance', 'The learners exhibit customer service relation skills.', 1, 6),
  ('sshs-grade-11-hotel-operation-housekeeping-services:standard:content:period-1:item-1', 'sshs-grade-11-hotel-operation-housekeeping-services', 1, null, 'content', 'The learners demonstrate understanding of the principles, practices, and standards of providing housekeeping services in the hospitality industry.', 1, 2),
  ('sshs-grade-11-hotel-operation-housekeeping-services:standard:performance:period-1:item-1', 'sshs-grade-11-hotel-operation-housekeeping-services', 1, null, 'performance', 'The learners demonstrate familiarity of the different types of hotels, classifications of guest and the services hotels provide to the guest.', 1, 2),
  ('sshs-grade-11-hotel-operation-housekeeping-services:standard:content:period-2:item-1', 'sshs-grade-11-hotel-operation-housekeeping-services', 2, null, 'content', 'The learners understand the principles, practices, and innovations in housekeeping services in accordance with industry standards. Analyze trends, organizational structures, room classifications, and service excellence in hospitality management, reflecting the demands of a globally competitive and sustainable tourism and hospitality sector.', 1, 4),
  ('sshs-grade-11-hotel-operation-housekeeping-services:standard:performance:period-2:item-1', 'sshs-grade-11-hotel-operation-housekeeping-services', 2, null, 'performance', 'The learners describe the functions of the different sections of the hotel, classify guest rooms and status.', 1, 4),
  ('sshs-grade-11-hotel-operation-housekeeping-services:standard:content:period-3:item-1', 'sshs-grade-11-hotel-operation-housekeeping-services', 3, null, 'content', 'The learners demonstrate understanding of the principles, methods, and techniques of housekeeping services, including the proper use, care, and maintenance of tools, equipment, and supplies, with emphasis on ergonomics, environmental sustainability, and best practices.', 1, 7),
  ('sshs-grade-11-hotel-operation-housekeeping-services:standard:performance:period-3:item-1', 'sshs-grade-11-hotel-operation-housekeeping-services', 3, null, 'performance', 'The learners perform the cleaning procedures of guest rooms in accordance to room status following Occupational Health and Safety standards.', 1, 7),
  ('sshs-grade-11-hotel-operation-housekeeping-services:standard:content:period-4:item-1', 'sshs-grade-11-hotel-operation-housekeeping-services', 4, null, 'content', 'The learners demonstrate understanding of the principles, techniques, and standards in housekeeping operations, including the identification and proper handling of hotel linens, laundry and ironing operations, personalized guest services, customer relations, facility evaluation, and housekeeping safety and security.', 1, 9),
  ('sshs-grade-11-hotel-operation-housekeeping-services:standard:performance:period-4:item-1', 'sshs-grade-11-hotel-operation-housekeeping-services', 4, null, 'performance', 'The learners exhibit techniques in linen management, laundry and ironing operations, valet/butler services, customer care, and apply effective strategies for handling complaints.', 1, 9),
  ('sshs-grade-11-human-movement-1-basic-anatomy-in-sports-and-exercise:standard:content:period-1:item-1', 'sshs-grade-11-human-movement-1-basic-anatomy-in-sports-and-exercise', 1, null, 'content', 'The learners demonstrate understanding of the basic structure and processes of the human body in relation to fitness, exercise, and health to optimize human movement.', 1, 2),
