  ('sshs-grade-11-human-movement-2-motor-skills-development:standard:content:period-1:item-1', 'sshs-grade-11-human-movement-2-motor-skills-development', 1, null, 'content', 'The learners demonstrate understanding of the fundamentals of motor skills development to optimize human movement.', 1, 2),
