  ('sshs-grade-11-illustration:standard:content:period-1:item-1', 'sshs-grade-11-illustration', 1, null, 'content', 'The learners demonstrate an understanding of the fundamentals of illustration and drawing techniques required to create basic shapes with the illusion of volume, figures, objects, and human figures using traditional drawing techniques.', 1, 2),
