  ('sshs-grade-11-illustration:standard:content:period-3:item-1', 'sshs-grade-11-illustration', 3, null, 'content', 'The learners demonstrate an understanding of gathering and analyzing information for concept art and the application of digital drawing techniques to create visually appealing concept art using appropriate digital media.', 1, 7),
