  ('sshs-grade-11-illustration:standard:content:period-4:item-1', 'sshs-grade-11-illustration', 4, null, 'content', 'The learners demonstrate an understanding of various illustration styles, analyzing design briefs, applying appropriate styles and techniques to create illustrations that effectively convey intended ideas using digital media, and to compute for design cost in illustration.', 1, 9),
